import type { Platform, PlatformOs } from './types.ts';
import { unsupported } from './types.ts';
import { createWebDevice } from './device-web.ts';

// The Capacitor platform adapter.
//
// It implements the same contract as the web adapter and nothing more. There is no product logic
// here and none in the Android or iOS projects: the shells package the shared application and answer
// the capability questions the operating system can answer. Everything a plugin cannot honestly
// provide keeps `supported: false` rather than a stub that pretends.
//
// The plugins arrive as a parameter instead of being imported here, so `tests/native-platform.test.ts`
// exercises this adapter — its listener bookkeeping, its URL handling, its capability answers — with
// fakes at the one boundary that genuinely cannot run in Node: the native bridge itself.

/** A Capacitor listener handle. Every `addListener` resolves to one of these. */
export type ListenerHandle = { remove(): Promise<void> };

/** The slices of the official plugins this adapter uses. Structural, so the real plugins satisfy it. */
export type NativePlugins = {
  app: {
    addListener(event: 'appStateChange', listener: (state: { isActive: boolean }) => void): Promise<ListenerHandle>;
    addListener(event: 'appUrlOpen', listener: (data: { url: string }) => void): Promise<ListenerHandle>;
    addListener(event: 'backButton', listener: (event: { canGoBack: boolean }) => void): Promise<ListenerHandle>;
    /** `moveTaskToBack(true)`: the app leaves the foreground and keeps its state, which is what
     * Android itself does when Back is pressed at the root of a task. */
    minimizeApp(): Promise<void>;
  };
  network: {
    getStatus(): Promise<{ connected: boolean }>;
    addListener(event: 'networkStatusChange', listener: (status: { connected: boolean }) => void): Promise<ListenerHandle>;
  };
  haptics: { impact(options: { style: string }): Promise<void> };
  keyboard: {
    addListener(event: 'keyboardWillShow' | 'keyboardWillHide', listener: () => void): Promise<ListenerHandle>;
  };
  statusBar: { setStyle(options: { style: string }): Promise<void> };
  splashScreen: { hide(): Promise<void> };
  preferences: {
    get(options: { key: string }): Promise<{ value: string | null }>;
    set(options: { key: string; value: string }): Promise<void>;
    remove(options: { key: string }): Promise<void>;
  };
};

/** The window bits the adapter reads; narrow so a test can pass a fake. */
export type NativeWindow = {
  addEventListener?(type: string, listener: () => void): void;
  removeEventListener?(type: string, listener: () => void): void;
  location?: { pathname?: string };
};

/**
 * Subscribes to a Capacitor event and returns a synchronous unsubscribe.
 *
 * `addListener` is asynchronous, so an unsubscribe can be called before the handle exists — a React
 * effect that mounts and unmounts in the same tick does exactly that. Without the `stopped` flag the
 * handle would arrive after the cleanup ran and the listener would stay attached for the life of the
 * process, which is how a WebView ends up firing one navigation per remount.
 */
export function subscribe(open: () => Promise<ListenerHandle>): () => void {
  let handle: ListenerHandle | null = null;
  let stopped = false;
  void open().then(opened => { if (stopped) void opened.remove().catch(() => {}); else handle = opened; }).catch(() => {});
  return () => {
    if (stopped) return;
    stopped = true;
    const opened = handle;
    handle = null;
    if (opened) void opened.remove().catch(() => {});
  };
}

/**
 * The application path inside a link that opened the app.
 *
 * Universal Links and App Links arrive as full `https://lgu.thegreekos.com/...` URLs; a custom scheme
 * arrives as `com.thegreekos.lgu://theme/oxi-1940`, where the first path segment is parsed as the
 * host. Both reduce to a path that `parseRoute` already understands, and anything unparseable becomes
 * `/`, which `parseRoute` resolves to home rather than throwing at boot.
 */
export function deepLinkPath(url: string): string {
  let parsed: URL;
  try { parsed = new URL(url); } catch { return url.startsWith('/') ? url : '/'; }
  if (parsed.protocol === 'http:' || parsed.protocol === 'https:') return parsed.pathname || '/';
  // A custom scheme has no authority, so `scheme://theme/x` parses `theme` as the host: it is part of the path.
  const path = `${parsed.host ? '/' + parsed.host : ''}${parsed.pathname}`;
  return path || '/';
}

/**
 * Builds the platform for a Capacitor runtime.
 *
 * `os` is the transport identity the backend already knows (`web | ios | android`) and is also the
 * Device Profile's declared runtime. Neither is widened here: a future TV or kiosk shell describes
 * itself with `DeviceRuntime` and still identifies to the API as one of these three.
 */
export function createNativePlatform(os: Exclude<PlatformOs, 'web'>, plugins: NativePlugins, appVersion: string, win?: NativeWindow): Platform {
  // `Network.online()` is synchronous by contract, so the adapter keeps the last known status and the
  // subscription refreshes it. Assuming "online" until told otherwise matches the browser adapter and
  // keeps a first request from being suppressed before the first status arrives.
  let online = true;
  void plugins.network.getStatus().then(status => { online = status.connected; }).catch(() => {});

  const platform: Platform = {
    isNative: true,
    os,
    appVersion,
    // The shell cannot hold a SameSite cookie for another origin; it presents the session explicitly.
    sessionTransport: 'bearer',
    clientHeader: () => `${os}/${appVersion}`,

    storage: {
      supported: true,
      // Capacitor Preferences is SharedPreferences on Android and UserDefaults on iOS. Both live in
      // the application sandbox; neither is encrypted at rest, so this stays false. Only a
      // Keychain / Keystore-backed adapter may ever state true. See docs/DECISIONS.md.
      secureAtRest: false,
      get: async key => { try { return (await plugins.preferences.get({ key })).value ?? null; } catch { return null; } },
      set: async (key, value) => { try { await plugins.preferences.set({ key, value }); } catch { /* storage full or unavailable */ } },
      remove: async key => { try { await plugins.preferences.remove({ key }); } catch { /* ignore */ } },
    },

    // Native push needs a Firebase Android application, an APNs key and a registered bundle id, none
    // of which exist for LGU yet. The backend, the device registry and the provider map already accept
    // `ios` and `android` devices; until the credentials are provisioned the honest answer is that
    // this shell cannot receive push, not a stub that reports a permission it could not obtain.
    // docs/push-notifications.md records exactly what provisioning unblocks this.
    notifications: unsupported({
      permission: async () => 'unsupported' as const,
      requestPermissionAndSubscribe: async () => ({ permission: 'unsupported' as const, registration: null }),
      currentRegistration: async () => null,
      unsubscribe: async () => false,
      onMessage: () => () => {},
    }),

    deepLinks: {
      supported: true,
      onOpen(listener) {
        // Two sources, one route parser: a link that opened the application, and the shell's own
        // history — the Android hardware back button pops it, and the application navigates on that
        // exactly as the browser does.
        const stopUrl = subscribe(() => plugins.app.addListener('appUrlOpen', data => listener(deepLinkPath(data.url))));
        const target = win ?? (typeof window === 'undefined' ? undefined : (window as NativeWindow));
        if (!target?.addEventListener) return stopUrl;
        const pop = () => listener(target.location?.pathname ?? '/');
        target.addEventListener('popstate', pop);
        return () => { stopUrl(); target.removeEventListener?.('popstate', pop); };
      },
    },

    // @capacitor/share is not part of this phase; nothing in the product shares yet. The capability
    // stays honestly unsupported rather than reporting a WebView `navigator.share` that is absent.
    share: unsupported({ share: async () => false }),

    network: {
      supported: true,
      online: () => online,
      onChange(listener) {
        return subscribe(() => plugins.network.addListener('networkStatusChange', status => {
          online = status.connected;
          listener(status.connected);
        }));
      },
    },

    lifecycle: {
      supported: true,
      onChange(listener) {
        return subscribe(() => plugins.app.addListener('appStateChange', state => listener(state.isActive ? 'active' : 'background')));
      },
    },

    haptics: {
      supported: true,
      async impact(style) {
        try { await plugins.haptics.impact({ style: style === 'heavy' ? 'HEAVY' : style === 'medium' ? 'MEDIUM' : 'LIGHT' }); } catch { /* a device without a taptic engine */ }
      },
    },

    keyboard: {
      supported: true,
      onChange(listener) {
        const stopShow = subscribe(() => plugins.keyboard.addListener('keyboardWillShow', () => listener(true)));
        const stopHide = subscribe(() => plugins.keyboard.addListener('keyboardWillHide', () => listener(false)));
        return () => { stopShow(); stopHide(); };
      },
    },

    // Local notifications would need the notification permission in both manifests. No product feature
    // schedules one, so no permission is declared and the capability stays unsupported.
    localNotifications: unsupported({ schedule: async () => false, cancel: async () => {} }),

    statusBar: {
      supported: true,
      // The contract's value names the status bar's own appearance, which is how Capacitor's `Style`
      // is defined too, so it passes straight through.
      async setStyle(style) { try { await plugins.statusBar.setStyle({ style: style === 'dark' ? 'DARK' : 'LIGHT' }); } catch { /* ignore */ } },
    },

    splashScreen: {
      supported: true,
      async hide() { try { await plugins.splashScreen.hide(); } catch { /* ignore */ } },
    },

    // @capacitor/screen-orientation is not installed: LGU is portrait-first and locks nothing.
    orientation: unsupported({ lock: async () => {} }),

    // The system Back button, which only Android has. iOS keeps `supported: false` rather than
    // subscribing to an event its operating system never sends.
    //
    // Subscribing is what fixes the dead key. @capacitor/app installs an enabled
    // `OnBackPressedCallback` whether or not anything is listening, and with no listener its own
    // handler does nothing at all once `canGoBack()` is false — it consumes the press and leaves the
    // activity in the foreground. With a listener the plugin forwards every press instead, so the
    // application decides both halves: follow its history, or leave.
    systemBack: os === 'android' ? {
      supported: true,
      onPress(listener) {
        return subscribe(() => plugins.app.addListener('backButton', event => listener({ canGoBack: !!event?.canGoBack })));
      },
      async leaveApp() { try { await plugins.app.minimizeApp(); } catch { /* not the root of the task */ } },
    } : unsupported({ onPress: () => () => {}, leaveApp: async () => {} }),

    // No feature needs them, so no permission is declared in AndroidManifest.xml or Info.plist.
    camera: { supported: false },
    microphone: { supported: false },
    files: { supported: false },

    // The Device Profile reuses the same browser signal reading — a Capacitor WebView reports touch,
    // pointer and viewport honestly — and declares only what the shell actually knows: the runtime.
    // It does **not** declare a form factor. Android exposes no reliable phone/tablet flag, and
    // inferring one from the viewport is exactly what the layer forbids, so it stays `unknown`.
    device: createWebDevice(() => platform, undefined, () => ({ runtime: os })),
  };
  return platform;
}
