// Presentation of an answer that has already been marked. This module never decides whether an answer
// is correct: the server did that once, when the answer was submitted, and its verdict travels with the
// feedback. Here we only lay out the rows of the card the learner is looking at, so the intermediate
// reveal can show "this is what I picked" next to "this was the right one" without a second evaluation.

import type { Kind } from './rules.ts';

export type RevealOption = { id: string; text: string; imageUrl?: string };
/** correct: the right answer. wrong: the learner put this here and it does not belong. idle: neither. */
export type RevealMark = 'correct' | 'wrong' | 'idle';
export type RevealRow = {
  id: string;
  text: string;
  imageUrl?: string;
  mark: RevealMark;
  /** True when the learner picked this option, or placed/paired it themselves. */
  chosen: boolean;
  /** 1-based slot number for ordered formats. */
  position?: number;
  /** match: the right-hand text the learner paired with this row. */
  answer?: string;
  /** match: the right-hand text that belonged here, when the pairing was wrong. */
  expected?: string;
};
export type RevealSheet = { layout: 'choice' | 'order' | 'match'; rows: RevealRow[] };

export function revealSheet({ kind, options, rightOptions, submitted, correctIds }: {
  kind: Kind;
  options: RevealOption[];
  rightOptions?: RevealOption[];
  submitted: readonly string[];
  correctIds: readonly string[];
}): RevealSheet {
  const textOf = (source: RevealOption[], id: string) => source.find(option => option.id === id)?.text ?? '';
  if (kind === 'order') {
    // The learner's own sequence, each slot marked against the sequence that was expected there.
    const placed = submitted.length === correctIds.length ? submitted : correctIds;
    return { layout: 'order', rows: placed.map((id, index) => ({
      id, text: textOf(options, id), mark: correctIds[index] === id ? 'correct' : 'wrong', chosen: true, position: index + 1,
    })) };
  }
  if (kind === 'match') {
    // One row per left-hand option, in the order the learner saw them, carrying both pairings.
    const right = rightOptions ?? [];
    return { layout: 'match', rows: options.map((option, index) => {
      const picked = submitted[index] ?? '';
      const correct = correctIds[index] === picked;
      return {
        id: option.id, text: option.text, mark: correct ? 'correct' : 'wrong', chosen: true,
        answer: textOf(right, picked), ...(correct ? {} : { expected: textOf(right, correctIds[index] ?? '') }),
      } satisfies RevealRow;
    }) };
  }
  // choice, boolean, image and cloze: every option keeps its position, so the card does not move.
  return { layout: 'choice', rows: options.map(option => ({
    id: option.id, text: option.text, imageUrl: option.imageUrl,
    mark: correctIds.includes(option.id) ? 'correct' : submitted.includes(option.id) ? 'wrong' : 'idle',
    chosen: submitted.includes(option.id),
  })) };
}
