'use client';
import { useEffect, useRef, type ButtonHTMLAttributes, type CSSProperties, type ReactNode, type Ref } from 'react';
import { Icon, type IconName } from './icons';
import type { Locale } from '../ui-types';
import { assetUrl } from '../engine/api-origin.ts';

/** Approved LGU application icon. Every branded surface reads from this one path. */
export const BRAND_ICON = '/brand/lgu-icon.png';

export function BrandMark({ size = 40, className = '' }: { size?: number; className?: string }) {
  return <span className={`brand-mark ${className}`} style={{ '--mark': `${size}px` } as CSSProperties} aria-hidden="true">
    <img src={assetUrl(BRAND_ICON)} alt="" width={size} height={size} />
  </span>;
}

export function BrandLockup({ locale, onClick }: { locale: Locale; onClick?: () => void }) {
  const el = locale === 'el';
  return <button type="button" className="brand-lockup" onClick={onClick} aria-label={el ? 'Little Greeks United, αρχική' : 'Little Greeks United, home'}>
    <BrandMark size={44} />
    <span><span className="brand-name">Little Greeks United</span><small>{el ? 'ΠΑΙΖΩ · ΜΑΘΑΙΝΩ' : 'PLAY · LEARN'}</small></span>
  </button>;
}

type Variant = 'primary' | 'secondary' | 'soft' | 'ghost' | 'danger';
export type ButtonProps = ButtonHTMLAttributes<HTMLButtonElement> & {
  ref?: Ref<HTMLButtonElement>;
  variant?: Variant;
  size?: 'sm' | 'md' | 'lg';
  block?: boolean;
  icon?: IconName;
  iconEnd?: IconName;
};
export function Button({ variant = 'primary', size = 'md', block, icon, iconEnd, className = '', children, type = 'button', ...rest }: ButtonProps) {
  const classes = ['btn', `btn-${variant}`, size !== 'md' ? `btn-${size}` : '', block ? 'btn-block' : '', className].filter(Boolean).join(' ');
  return <button type={type} className={classes} {...rest}>
    {icon && <Icon name={icon} />}{children}{iconEnd && <Icon name={iconEnd} />}
  </button>;
}

export function IconButton({ label, icon, className = '', ...rest }: ButtonHTMLAttributes<HTMLButtonElement> & { label: string; icon: IconName }) {
  return <button type="button" className={`btn-icon ${className}`} aria-label={label} title={label} {...rest}><Icon name={icon} /></button>;
}

export function BackButton({ onClick, children, label, className = '' }: { onClick: () => void; children: ReactNode; label?: string; className?: string }) {
  return <button type="button" className={`back-link ${className}`} onClick={onClick} aria-label={label}><Icon name="arrow-left" />{children}</button>;
}

export function Card({ tint, pad = true, className = '', children, as: Tag = 'div' }: { tint?: 'blue' | 'green' | 'red' | 'orange' | 'purple'; pad?: boolean; className?: string; children: ReactNode; as?: 'div' | 'section' | 'article' | 'aside' }) {
  return <Tag className={['card', pad ? 'card--pad' : '', tint ? `card--tint-${tint}` : '', className].filter(Boolean).join(' ')}>{children}</Tag>;
}

export function PageContainer({ width = 'default', className = '', children }: { width?: 'default' | 'narrow' | 'form'; className?: string; children: ReactNode }) {
  return <div className={['page', width === 'narrow' ? 'page--narrow' : '', width === 'form' ? 'page--form' : '', className].filter(Boolean).join(' ')}>{children}</div>;
}

export function PageHead({ title, lead, eyebrow, aside }: { title: ReactNode; lead?: ReactNode; eyebrow?: ReactNode; aside?: ReactNode }) {
  return <div className="page-head"><div>{eyebrow && <span className="eyebrow">{eyebrow}</span>}<h1>{title}</h1>{lead && <p className="lead">{lead}</p>}</div>{aside}</div>;
}

export function Pill({ tone = 'neutral', icon, className = '', children }: { tone?: 'blue' | 'green' | 'red' | 'orange' | 'purple' | 'neutral' | 'onimage'; icon?: IconName; className?: string; children: ReactNode }) {
  return <span className={`pill pill--${tone} ${className}`}>{icon && <Icon name={icon} />}{children}</span>;
}

export function StatPill({ icon, value, label, tone }: { icon: IconName; value: ReactNode; label: ReactNode; tone?: 'green' | 'red' | 'orange' }) {
  return <div className={`stat-pill ${tone ? `stat-pill--${tone}` : ''}`}><Icon name={icon} /><strong>{value}</strong><span>{label}</span></div>;
}

export function ProgressBar({ value, label, tone, small, onImage }: { value: number; label: string; tone?: 'green' | 'orange'; small?: boolean; onImage?: boolean }) {
  const clamped = Math.max(0, Math.min(100, value));
  return <div className={['progress', small ? 'progress--sm' : '', tone ? `progress--${tone}` : '', onImage ? 'progress--onimage' : ''].filter(Boolean).join(' ')} role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={clamped} aria-label={label}>
    <span style={{ width: `${clamped}%` }} />
  </div>;
}

export function ProgressRing({ value, size = 128, stroke = 10, tone, label, className = '', children }: { value: number; size?: number; stroke?: number; tone?: 'green' | 'red'; label: string; className?: string; children: ReactNode }) {
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const clamped = Math.max(0, Math.min(100, value));
  return <div className={`ring ${tone ? `ring--${tone}` : ''} ${className}`} style={{ width: size, height: size }} role="img" aria-label={label}>
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`}>
      <circle className="ring-track" cx={size / 2} cy={size / 2} r={radius} strokeWidth={stroke} />
      <circle className="ring-value" cx={size / 2} cy={size / 2} r={radius} strokeWidth={stroke} strokeDasharray={circumference} strokeDashoffset={circumference * (1 - clamped / 100)} />
    </svg>
    <div className="ring-label">{children}</div>
  </div>;
}

export function Segmented<T extends string>({ options, value, onChange, label }: { options: { id: T; label: string }[]; value: T; onChange: (value: T) => void; label: string }) {
  return <div className="segmented" role="group" aria-label={label}>
    {options.map(option => <button key={option.id} type="button" aria-pressed={value === option.id} className={value === option.id ? 'active' : ''} onClick={() => onChange(option.id)}>{option.label}</button>)}
  </div>;
}

export function Avatar({ name, size = 'md', className = '' }: { name: string; size?: 'md' | 'lg'; className?: string }) {
  return <span className={`avatar ${size === 'lg' ? 'avatar--lg' : ''} ${className}`} aria-hidden="true">{name.trim().slice(0, 1) || '?'}</span>;
}

export function LanguageSwitch({ locale, onChange, busy, className = '' }: { locale: Locale; onChange: (locale: Locale) => void; busy: boolean; className?: string }) {
  return <div className={`language-switch ${className}`} role="group" aria-label={locale === 'el' ? 'Γλώσσα' : 'Language'}>
    <button type="button" aria-pressed={locale === 'el'} className={locale === 'el' ? 'active' : ''} disabled={busy} onClick={() => onChange('el')}>ΕΛ</button>
    <button type="button" aria-pressed={locale === 'en'} className={locale === 'en' ? 'active' : ''} disabled={busy} onClick={() => onChange('en')}>EN</button>
  </div>;
}

export function Alert({ locale, children, onClose }: { locale: Locale; children: ReactNode; onClose: () => void }) {
  return <div className="alert-wrap"><div className="alert" role="alert">{children}<button type="button" aria-label={locale === 'el' ? 'Κλείσιμο μηνύματος' : 'Close message'} onClick={onClose}><Icon name="x" /></button></div></div>;
}

export function EmptyState({ icon = 'sparkle', tone = 'blue', title, lead, action }: { icon?: IconName; tone?: 'blue' | 'green' | 'orange'; title: ReactNode; lead?: ReactNode; action?: ReactNode }) {
  return <div className="empty-state card"><span className={`feedback-icon feedback-icon--${tone}`}><Icon name={icon} /></span><h2>{title}</h2>{lead && <p>{lead}</p>}{action}</div>;
}

export function LoadingScreen({ locale }: { locale: Locale }) {
  return <main className="loading" aria-busy="true"><BrandMark size={96} /><span className="spinner" aria-hidden="true" /><p>{locale === 'el' ? 'Ετοιμάζουμε το ταξίδι σου…' : 'Preparing your journey…'}</p></main>;
}

export function Modal({ locale, label, onClose, children }: { locale: Locale; label: string; onClose: () => void; children: ReactNode }) {
  const panel = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const previous = document.activeElement as HTMLElement | null;
    const focusable = panel.current?.querySelector<HTMLElement>('button, [href], input, select, textarea');
    focusable?.focus();
    const onKey = (event: KeyboardEvent) => { if (event.key === 'Escape') onClose(); };
    document.addEventListener('keydown', onKey);
    const { overflow } = document.body.style;
    document.body.style.overflow = 'hidden';
    return () => { document.removeEventListener('keydown', onKey); document.body.style.overflow = overflow; previous?.focus(); };
  }, [onClose]);
  return <div className="modal-backdrop" onClick={event => { if (event.target === event.currentTarget) onClose(); }}>
    <div ref={panel} className="modal" role="dialog" aria-modal="true" aria-label={label}>
      <IconButton className="modal-close" icon="x" label={locale === 'el' ? 'Κλείσιμο' : 'Close'} onClick={onClose} />
      {children}
    </div>
  </div>;
}
