import type { Platform } from '../platform/types.ts';
import { getPlatform } from '../platform/index.ts';
import { assetUrl } from './api-origin.ts';
import { sessionRequestHeaders } from './session.ts';

// Narrated audio: the one place the application turns an API audio path into something an audio
// element can play.
//
// WHY THIS EXISTS
// `/api/audio` is an authenticated route. In a browser that has always been invisible: the document
// and the API share an origin, so `new Audio('/api/audio?…')` resolved correctly and the browser
// attached the HttpOnly session cookie by itself. Both halves of that stop being true in a packaged
// shell, and the Android emulator acceptance on 18 September 2026 found them stacked:
//
//  1. the shell serves its UI from the device, so a root-relative path resolves against
//     `https://localhost` — the bundle, which carries no audio. The bundle answered the unknown path
//     with the SPA document and the element died on a 200 `text/html`.
//  2. with the origin corrected, the request is cross-site. No cookie is sent — the CORS policy
//     deliberately withholds `Access-Control-Allow-Credentials` — the session travels as a bearer
//     token instead, and an `<audio>` element cannot attach an Authorization header. 401.
//
// So the element can no longer fetch its own media, and this module fetches it instead: resolve the
// path through `assetUrl`, ask the session boundary for the headers, validate what came back, and
// hand the element a `blob:` URL over bytes already in memory. Clips are ~60 KB, so buffering a
// whole clip costs nothing measurable and buys one answer that is the same on both platforms.
//
// WHY NOT A SIGNED URL
// A short-lived signed URL would let the element fetch for itself, at the price of a second
// credential format — one that lives in a URL, and that needs a signing secret, an expiry policy and
// its own verification path beside the session the backend already has. This keeps one credential,
// and keeps it out of every URL. See `docs/DECISIONS.md`.
//
// WHAT THE BROWSER GETS
// Exactly what it had. `credentials: 'same-origin'` attaches the same HttpOnly cookie the element
// used to send, `sessionRequestHeaders` adds nothing at all on the web, and no script ever holds a
// credential. Nothing about the cookie, CSRF or CORS is relaxed to make any of this work.

/** The narrow view of the platform this module needs: how the session travels, and who is asking. */
type AudioPlatform = Pick<Platform, 'sessionTransport' | 'clientHeader'>;

/** Object-URL lifetime, injectable so the cleanup contract can be asserted rather than assumed. */
export type ObjectUrls = { create(blob: Blob): string; revoke(url: string): void };
const platformObjectUrls: ObjectUrls = { create: blob => URL.createObjectURL(blob), revoke: url => URL.revokeObjectURL(url) };

/** A clip held in memory as a `blob:` URL. Whoever takes one is responsible for releasing it. */
export type AudioSource = { readonly url: string; readonly type: string; readonly bytes: number; release(): void };

/**
 * Why a clip could not be played: a small closed set of causes rather than a message. An error
 * string is the classic way a credential reaches a log, and nothing in this set can carry one.
 */
export type AudioFailure = 'aborted' | 'unauthorized' | 'forbidden' | 'unavailable' | 'server' | 'network' | 'not-audio' | 'empty';

export class AudioLoadError extends Error {
  readonly failure: AudioFailure;
  readonly status: number | null;
  constructor(failure: AudioFailure, status: number | null = null) {
    super(`audio: ${failure}${status === null ? '' : ` (${status})`}`);
    this.name = 'AudioLoadError';
    this.failure = failure;
    this.status = status;
  }
}

/**
 * Only a real audio media type is played.
 *
 * This is the check that turns the first defect into a clear failure rather than a mysterious one: a
 * bundle answering an unknown path with `200 text/html`, a captive-portal interstitial and a JSON
 * error body are all successful HTTP responses, and none of them is media.
 */
export function isPlayableAudioType(contentType: string | null | undefined): boolean {
  const type = (contentType ?? '').split(';')[0].trim().toLowerCase();
  return type.startsWith('audio/') && type.length > 'audio/'.length;
}

const failureForStatus = (status: number): AudioFailure =>
  status === 401 ? 'unauthorized' : status === 403 ? 'forbidden' : status >= 500 ? 'server' : 'unavailable';

const wasAborted = (error: unknown, signal?: AbortSignal) =>
  signal?.aborted === true || (typeof error === 'object' && error !== null && (error as { name?: string }).name === 'AbortError');

export type AudioLoadOptions = {
  signal?: AbortSignal;
  platform?: AudioPlatform;
  fetch?: typeof globalThis.fetch;
  objectUrls?: ObjectUrls;
};

/**
 * Fetches one clip with the current session and returns it as an object URL.
 *
 * The path is whatever the API put in `AudioItem.url` — root-relative today. It is resolved by
 * `assetUrl`, the same resolver every image goes through, so a packaged shell addresses the deployed
 * origin while a browser keeps the relative URL it always had. The credential is never appended to
 * it, and the object URL that comes back carries nothing but the bytes.
 */
export async function loadAudio(path: string, options: AudioLoadOptions = {}): Promise<AudioSource> {
  const platform = options.platform ?? getPlatform();
  // Called through the global rather than passed by reference: a detached `fetch` is an illegal
  // invocation in strict-mode module code on some engines.
  const request: typeof globalThis.fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
  const objectUrls = options.objectUrls ?? platformObjectUrls;
  let response: Response;
  try {
    response = await request(assetUrl(path), {
      method: 'GET',
      // Browser: this is what attaches the HttpOnly cookie, exactly as the element used to.
      // Shell: its own origin holds no cookie, and the header below carries the session instead.
      credentials: 'same-origin',
      headers: { 'X-LGU-Client': platform.clientHeader(), ...sessionRequestHeaders(platform) },
      signal: options.signal,
    });
  } catch (error) {
    throw new AudioLoadError(wasAborted(error, options.signal) ? 'aborted' : 'network');
  }
  if (!response.ok) throw new AudioLoadError(failureForStatus(response.status), response.status);
  if (!isPlayableAudioType(response.headers.get('content-type'))) throw new AudioLoadError('not-audio', response.status);
  let blob: Blob;
  try { blob = await response.blob(); }
  catch (error) { throw new AudioLoadError(wasAborted(error, options.signal) ? 'aborted' : 'network', response.status); }
  if (!blob.size) throw new AudioLoadError('empty', response.status);
  // Abandoned while the body was being read: create nothing, so there is nothing to leak.
  if (options.signal?.aborted) throw new AudioLoadError('aborted');
  const url = objectUrls.create(blob);
  let released = false;
  return {
    url,
    type: blob.type,
    bytes: blob.size,
    release() { if (released) return; released = true; objectUrls.revoke(url); },
  };
}

/** The part of an audio element this module drives. A real `HTMLAudioElement` satisfies it. */
export type PlaybackElement = {
  play(): unknown;
  pause(): void;
  onended: ((...args: any[]) => any) | null;
  onerror: ((...args: any[]) => any) | null;
  removeAttribute(name: string): void;
  load?(): void;
};

export type NarrationPlayerOptions = {
  load?: (path: string, options: { signal: AbortSignal }) => Promise<AudioSource>;
  element?: (src: string) => PlaybackElement;
  onActiveChange?: (active: boolean) => void;
  onPlayingChange?: (playing: boolean) => void;
  onFailure?: (failure: AudioFailure) => void;
};

export type NarrationPlayer = {
  /** Plays the clips in order. Any earlier request — still loading, or playing — is abandoned first. */
  play(items: readonly { url: string }[]): void;
  /** Stops playback, abandons an in-flight load and releases every object URL this player created. */
  stop(): void;
  /**
   * True from the tap that asked for narration until it ends, fails or is stopped — **including the
   * time the first clip is still downloading**.
   *
   * This is the state a control should follow, and it is separate from `playing` on purpose. A clip
   * arrives over the network: on a slow connection there is a real window in which the learner has
   * asked for audio and none is playing yet. A control driven by `playing` still reads "Listen"
   * during that window, so the next tap starts a *second* request instead of cancelling the first,
   * and the request the learner wanted to stop cannot be stopped from the only control there is.
   */
  active(): boolean;
  /** True only while an element is actually playing media. Never true for a clip that is still loading. */
  playing(): boolean;
};

/**
 * Sequences clips, and owns the two lifetimes a fetched clip introduces: the request and the object
 * URL. Both are easy to get wrong, neither is visible from a screen, and so neither is a screen's job.
 *
 * The rule is that the most recent intent wins. Every request is stamped with a generation, and both
 * `play` and `stop` raise it and abort whatever is in flight, so a clip that finishes loading after
 * the learner has moved on is released and never reaches an element. A URL is revoked only once the
 * element that was using it has been detached, because revoking underneath a live element is itself
 * a media error.
 *
 * It is deliberately free of React and of the DOM, so all of the above can be asserted directly.
 */
export function createNarrationPlayer(options: NarrationPlayerOptions = {}): NarrationPlayer {
  const load = options.load ?? ((path, init) => loadAudio(path, init));
  const element = options.element ?? ((src: string) => new Audio(src));
  let generation = 0;
  let current: PlaybackElement | null = null;
  let source: AudioSource | null = null;
  let controller: AbortController | null = null;
  let active = false;
  let playing = false;

  const setActive = (value: boolean) => {
    if (active === value) return;
    active = value;
    options.onActiveChange?.(value);
  };

  const setPlaying = (value: boolean) => {
    if (playing === value) return;
    playing = value;
    options.onPlayingChange?.(value);
  };

  // Detach first, revoke second: the element must no longer hold the URL when the URL stops existing.
  const releasePlayback = () => {
    if (current) {
      current.onended = null;
      current.onerror = null;
      current.pause();
      current.removeAttribute('src');
      current.load?.();
      current = null;
    }
    source?.release();
    source = null;
  };

  const abandon = () => {
    generation++;
    controller?.abort();
    controller = null;
    releasePlayback();
  };

  const stop = () => { abandon(); setPlaying(false); setActive(false); };

  const play = (items: readonly { url: string }[]) => {
    abandon();
    setPlaying(false);
    const queue = items.filter(item => typeof item?.url === 'string' && item.url.length > 0);
    // Nothing to play is not an intent: the control must not offer to stop what never started.
    if (!queue.length) { setActive(false); return; }
    // Synchronously, before the first byte is requested. This is what lets the control become Stop
    // straight away, so the tap that follows cancels this request instead of starting another.
    setActive(true);
    const token = generation;
    controller = new AbortController();
    const signal = controller.signal;
    let index = 0;
    const fail = (failure: AudioFailure) => { stop(); options.onFailure?.(failure); };
    const next = () => {
      if (token !== generation) return;
      if (index >= queue.length) { stop(); return; }
      load(queue[index++].url, { signal }).then(loaded => {
        if (token !== generation) { loaded.release(); return; }
        releasePlayback();
        source = loaded;
        const player = element(loaded.url);
        current = player;
        player.onended = () => { if (token === generation) next(); };
        player.onerror = () => { if (token === generation) fail('network'); };
        setPlaying(true);
        Promise.resolve(player.play()).catch(() => { if (token === generation) fail('network'); });
      }, (error: unknown) => {
        if (token !== generation) return;
        const failure = error instanceof AudioLoadError ? error.failure : 'network';
        // An abandoned request is not a failure: something newer already owns the player.
        if (failure !== 'aborted') fail(failure);
      });
    };
    next();
  };

  return { play, stop, active: () => active, playing: () => playing };
}
