import type { Platform, PushPermission, PushRegistration } from './types.ts';
import { unsupported } from './types.ts';
import { createWebDevice } from './device-web.ts';
import { registerServiceWorker, serviceWorkerSupported } from '../engine/service-worker.ts';

// The web platform: real implementations for what browsers provide, honest "unsupported" for the rest.

const APP_VERSION = process.env.NEXT_PUBLIC_LGU_APP_VERSION || '0.0.0';

function base64UrlToBytes(value: string) {
  const padded = (value + '='.repeat((4 - value.length % 4) % 4)).replace(/-/g, '+').replace(/_/g, '/');
  const raw = atob(padded);
  return Uint8Array.from(raw, character => character.charCodeAt(0));
}

function pushSupported() {
  return serviceWorkerSupported() && 'PushManager' in window && 'Notification' in window;
}

async function subscriptionToRegistration(subscription: PushSubscription | null): Promise<PushRegistration | null> {
  if (!subscription) return null;
  const json = subscription.toJSON();
  if (!json.endpoint || !json.keys?.p256dh || !json.keys?.auth) return null;
  return { platform: 'web', provider: 'webpush', subscription: { endpoint: json.endpoint, keys: { p256dh: json.keys.p256dh, auth: json.keys.auth }, expirationTime: json.expirationTime ?? null }, endpointKey: json.endpoint };
}

export function createWebPlatform(): Platform {
  const listen = <E extends Event>(target: EventTarget, type: string, handler: (event: E) => void) => { target.addEventListener(type, handler as EventListener); return () => target.removeEventListener(type, handler as EventListener); };
  const platform: Platform = {
    isNative: false, os: 'web', appVersion: APP_VERSION,
    // The browser keeps the session in an HttpOnly cookie that scripts cannot read.
    sessionTransport: 'cookie',
    clientHeader: () => `web/${APP_VERSION}`,
    storage: {
      supported: typeof localStorage !== 'undefined',
      // localStorage is readable by any script on the origin and is not encrypted at rest. Only a native
      // Keychain / Keystore adapter may state true here.
      secureAtRest: false,
      get: async key => { try { return localStorage.getItem(key); } catch { return null; } },
      set: async (key, value) => { try { localStorage.setItem(key, value); } catch { /* quota or privacy mode */ } },
      remove: async key => { try { localStorage.removeItem(key); } catch { /* ignore */ } },
    },
    notifications: {
      supported: typeof window !== 'undefined' && pushSupported(),
      async permission(): Promise<PushPermission> { return pushSupported() ? (Notification.permission as PushPermission) : 'unsupported'; },
      async requestPermissionAndSubscribe(applicationServerKey) {
        if (!pushSupported()) return { permission: 'unsupported', registration: null };
        const permission = (await Notification.requestPermission()) as PushPermission;
        if (permission !== 'granted') return { permission, registration: null };
        const registration = await registerServiceWorker();
        if (!registration) return { permission, registration: null };
        const existing = await registration.pushManager.getSubscription();
        const subscription = existing ?? await registration.pushManager.subscribe({ userVisibleOnly: true, applicationServerKey: base64UrlToBytes(applicationServerKey) as BufferSource });
        return { permission, registration: await subscriptionToRegistration(subscription) };
      },
      async currentRegistration() {
        if (!pushSupported() || Notification.permission !== 'granted') return null;
        const registration = await navigator.serviceWorker.getRegistration('/');
        return subscriptionToRegistration(await registration?.pushManager.getSubscription() ?? null);
      },
      async unsubscribe() {
        if (!pushSupported()) return false;
        const registration = await navigator.serviceWorker.getRegistration('/');
        const subscription = await registration?.pushManager.getSubscription();
        return subscription ? subscription.unsubscribe() : false;
      },
      onMessage(listener) {
        if (!serviceWorkerSupported()) return () => {};
        const handler = (event: MessageEvent) => { if (event.data && typeof event.data.type === 'string') listener(event.data); };
        navigator.serviceWorker.addEventListener('message', handler);
        return () => navigator.serviceWorker.removeEventListener('message', handler);
      },
    },
    deepLinks: {
      supported: typeof window !== 'undefined',
      onOpen(listener) {
        if (typeof window === 'undefined') return () => {};
        const pop = () => listener(window.location.pathname);
        const stopPop = listen(window, 'popstate', pop);
        const stopMessage = serviceWorkerSupported() ? (() => { const handler = (event: MessageEvent) => { if (event.data?.type === 'lgu-navigate' && typeof event.data.url === 'string') listener(event.data.url); }; navigator.serviceWorker.addEventListener('message', handler); return () => navigator.serviceWorker.removeEventListener('message', handler); })() : () => {};
        return () => { stopPop(); stopMessage(); };
      },
    },
    share: {
      supported: typeof navigator !== 'undefined' && typeof navigator.share === 'function',
      async share(data) { try { await navigator.share(data); return true; } catch { return false; } },
    },
    network: {
      supported: typeof navigator !== 'undefined' && 'onLine' in navigator,
      online: () => typeof navigator === 'undefined' ? true : navigator.onLine,
      onChange(listener) { if (typeof window === 'undefined') return () => {}; const on = listen(window, 'online', () => listener(true)); const off = listen(window, 'offline', () => listener(false)); return () => { on(); off(); }; },
    },
    lifecycle: {
      supported: typeof document !== 'undefined',
      onChange(listener) { if (typeof document === 'undefined') return () => {}; return listen(document, 'visibilitychange', () => listener(document.visibilityState === 'visible' ? 'active' : 'background')); },
    },
    haptics: {
      supported: typeof navigator !== 'undefined' && typeof navigator.vibrate === 'function',
      async impact(style) { try { navigator.vibrate(style === 'heavy' ? 30 : style === 'medium' ? 20 : 10); } catch { /* ignore */ } },
    },
    keyboard: unsupported({ onChange: () => () => {} }),
    localNotifications: unsupported({ schedule: async () => false, cancel: async () => {} }),
    statusBar: unsupported({ setStyle: async () => {} }),
    splashScreen: unsupported({ hide: async () => {} }),
    orientation: unsupported({ lock: async () => {} }),
    // A browser has no system Back to take over. Its Back button is history, and the application
    // already follows that through `deepLinks.onOpen` above — taking it over here would break it.
    systemBack: unsupported({ onPress: () => () => {}, leaveApp: async () => {} }),
    camera: { supported: false },
    microphone: { supported: false },
    files: { supported: false },
    // Device Profile: browser signals only; the feature view is derived from the adapters above.
    device: createWebDevice(() => platform),
  };
  return platform;
}
