import type { Localized } from './i18n.ts';

// Media references are data, never code. A reference names an asset by URL (bundled path or remote
// HTTPS location), carries the accessibility text that belongs to it and an optional version for cache
// busting. Resolution against a base URL happens at the edge (server response or client render), so the
// same theme definition serves the web app today and the native shells later without a rebuild.

export type MediaKind = 'image' | 'audio' | 'video';

/**
 * An optional moving companion to a still image — the seamless loop a later release may show where
 * the illustration is today.
 *
 * It is deliberately a *companion*, not an alternative: the reference's own `url` stays the poster and
 * the fallback, so a client that has never heard of this field, or a release that has the field but
 * not the player, shows exactly the picture it shows now. Nothing here makes anything move on its
 * own: the server only passes it on while the `themeMotion` feature is switched on.
 *
 * The format a file must meet to be accepted here is written down in `docs/STONE_AGE.md`: about ten
 * seconds, 4:3, 720p, no embedded audio, restrained movement, and a loop checked by watching the join
 * rather than by trusting that the first and last frames match.
 */
export type MotionRef = {
  url: string;
  /** Nominal length in seconds, for a client that wants to budget the download. */
  durationSeconds?: number;
};

/**
 * How a picture meets a frame whose shape it does not share. `cover` fills the frame and crops what
 * does not fit — the historical behaviour and the default; `contain` shows the whole picture and
 * lets the frame's background show around it. A card whose caption names something at the edge of the
 * picture is what `contain` exists for.
 */
export type MediaFit = 'cover' | 'contain';
export const MEDIA_FITS: readonly MediaFit[] = ['cover', 'contain'];
/** Where a cropped picture keeps its centre of attention, as fractions of its width and height. */
export type MediaFocus = { x: number; y: number };

export type MediaRef = {
  url: string;
  kind?: MediaKind;
  alt?: Localized;
  caption?: Localized;
  /** Content version; changes the resolved URL so caches refetch a replaced asset. */
  version?: string;
  width?: number;
  height?: number;
  /** Optional motion companion. The still `url` above remains mandatory and remains the poster. */
  motion?: MotionRef;
  /** Controlled cropping: absent means `cover`, which is what every stored reference has always done. */
  fit?: MediaFit;
  /** The point a `cover` crop keeps in view; absent means the centre. Ignored for `contain`. */
  focus?: MediaFocus;
};

export const isMediaFit = (value: unknown): value is MediaFit => typeof value === 'string' && (MEDIA_FITS as readonly string[]).includes(value);
export const isMediaFocus = (value: unknown): value is MediaFocus => !!value && typeof value === 'object' && !Array.isArray(value)
  && typeof (value as MediaFocus).x === 'number' && typeof (value as MediaFocus).y === 'number'
  && (value as MediaFocus).x >= 0 && (value as MediaFocus).x <= 1 && (value as MediaFocus).y >= 0 && (value as MediaFocus).y <= 1;

/** The fit and focus of a reference, or of a learning card, with the defaults an older document implies. */
export function mediaPlacement(value: { fit?: unknown; focus?: unknown } | null | undefined): { fit: MediaFit; focus: MediaFocus } {
  return { fit: isMediaFit(value?.fit) ? value!.fit : 'cover', focus: isMediaFocus(value?.focus) ? { x: value!.focus.x, y: value!.focus.y } : { x: 0.5, y: 0.5 } };
}

export type MediaPolicy = {
  /** Path prefixes served by the application origin (bundled today, remote base URL later). */
  allowedPaths: readonly string[];
  /** HTTPS hosts (exact, or "*.example.org" for subdomains) allowed for remote media. */
  allowedHosts: readonly string[];
};

export const DEFAULT_MEDIA_POLICY: MediaPolicy = {
  allowedPaths: ['/learning-assets/', '/question-assets/', '/brand/', '/Videos/', '/media/'],
  allowedHosts: [],
};

/**
 * Reviewed bundled SVG illustrations. SVG is only accepted from this list because it can carry scripts.
 * The list is empty since the twelve Oxi schematics were retired for the owner's approved webp
 * renderings (20 September 2026): no learning illustration is an SVG any more, and a reference to one
 * of the old files is refused rather than shown. Answer icons under /question-assets/ are not affected.
 */
export const REVIEWED_SVG_ASSETS: readonly string[] = [];

/** Neutral bundled placeholders shown when an asset is missing or fails to load. */
export const MEDIA_FALLBACK: Record<MediaKind, string> = {
  image: '/brand/lgu-icon.png',
  audio: '',
  video: '',
};

const RELATIVE_PATH = /^\/[A-Za-z0-9][A-Za-z0-9_\-./]*$/;

export function hostAllowed(host: string, allowedHosts: readonly string[]) {
  return allowedHosts.some(allowed => allowed.startsWith('*.') ? host === allowed.slice(2) || host.endsWith(allowed.slice(1)) : host === allowed);
}

export type MediaCheck = { ok: true; remote: boolean } | { ok: false; reason: string };

/** Accepts bundled paths under the allowed prefixes or HTTPS URLs on allowed hosts; nothing else. */
export function validateMediaUrl(url: unknown, policy: MediaPolicy = DEFAULT_MEDIA_POLICY): MediaCheck {
  if (typeof url !== 'string' || !url || url.length > 2048) return { ok: false, reason: 'MEDIA_URL_REQUIRED' };
  if (url.startsWith('/')) {
    if (!RELATIVE_PATH.test(url) || url.includes('/../') || url.includes('/./') || url.endsWith('/..')) return { ok: false, reason: 'MEDIA_PATH_INVALID' };
    if (!policy.allowedPaths.some(prefix => url.startsWith(prefix))) return { ok: false, reason: 'MEDIA_PATH_NOT_ALLOWED' };
    if (url.endsWith('.svg') && !REVIEWED_SVG_ASSETS.includes(url) && !url.startsWith('/question-assets/')) return { ok: false, reason: 'MEDIA_SVG_NOT_REVIEWED' };
    return { ok: true, remote: false };
  }
  let parsed: URL;
  try { parsed = new URL(url); } catch { return { ok: false, reason: 'MEDIA_URL_INVALID' }; }
  if (parsed.protocol !== 'https:' || parsed.username || parsed.password) return { ok: false, reason: 'MEDIA_URL_INSECURE' };
  if (!hostAllowed(parsed.hostname, policy.allowedHosts)) return { ok: false, reason: 'MEDIA_HOST_NOT_ALLOWED' };
  return { ok: true, remote: true };
}

/**
 * Where an answer picture may come from: a bundled answer icon, a raster the media policy serves —
 * `/question-assets/`, `/learning-assets/`, or a private theme's own uploaded `/media/<topic>/` file —
 * or any HTTPS location without credentials, which is what image questions have always accepted.
 * Lives here, with no server import, because the builder checks it in the browser as well.
 */
export function optionImageAllowed(imageUrl: unknown, policy: MediaPolicy = DEFAULT_MEDIA_POLICY): boolean {
  if (typeof imageUrl !== 'string' || !imageUrl) return false;
  if (/^\/question-assets\/[a-z0-9-]+\.svg$/.test(imageUrl)) return true;
  if (imageUrl.startsWith('/')) {
    const check = validateMediaUrl(imageUrl, policy);
    return check.ok && /\.(webp|png|jpg|jpeg)$/i.test(imageUrl.split('?')[0]);
  }
  try { const url = new URL(imageUrl); return url.protocol === 'https:' && !url.username && !url.password; }
  catch { return false; }
}
/** Whether a URL names a file this engine would play as motion. Extension only: the policy did the rest. */
export function isMotionUrl(url: string): boolean {
  return /\.(mp4|webm)(\?|$)/i.test(url);
}

/** Structural check of an optional motion companion. Null when there is none or it is sound. */
export function validateMotionRef(value: unknown, policy: MediaPolicy = DEFAULT_MEDIA_POLICY): string | null {
  if (value === undefined) return null;
  if (!value || typeof value !== 'object' || Array.isArray(value)) return 'MOTION_REF_INVALID';
  const ref = value as MotionRef;
  const url = validateMediaUrl(ref.url, policy);
  if (!url.ok) return url.reason;
  if (!isMotionUrl(ref.url)) return 'MOTION_FORMAT_NOT_SUPPORTED';
  if (ref.durationSeconds !== undefined && (typeof ref.durationSeconds !== 'number' || !(ref.durationSeconds > 0) || ref.durationSeconds > 60)) return 'MOTION_DURATION_INVALID';
  return null;
}

/** Structural check of a media reference (URL policy, kind, optional texts and version). */
export function validateMediaRef(value: unknown, policy: MediaPolicy = DEFAULT_MEDIA_POLICY): string | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return 'MEDIA_REF_REQUIRED';
  const ref = value as MediaRef;
  const url = validateMediaUrl(ref.url, policy);
  if (!url.ok) return url.reason;
  const motion = validateMotionRef(ref.motion, policy);
  if (motion) return motion;
  // A still that is itself a video has no poster to fall back to, which is the whole contract here.
  if (ref.motion && isMotionUrl(ref.url)) return 'MOTION_REQUIRES_STILL_POSTER';
  if (ref.kind !== undefined && !['image', 'audio', 'video'].includes(ref.kind)) return 'MEDIA_KIND_INVALID';
  if (ref.version !== undefined && (typeof ref.version !== 'string' || !/^[A-Za-z0-9._-]{1,40}$/.test(ref.version))) return 'MEDIA_VERSION_INVALID';
  for (const field of ['width', 'height'] as const) {
    if (ref[field] !== undefined && (!Number.isInteger(ref[field]) || (ref[field] as number) <= 0)) return 'MEDIA_SIZE_INVALID';
  }
  if (ref.fit !== undefined && !isMediaFit(ref.fit)) return 'MEDIA_FIT_INVALID';
  if (ref.focus !== undefined && !isMediaFocus(ref.focus)) return 'MEDIA_FOCUS_INVALID';
  return null;
}

/** Final URL for a client: relative assets join the configured base, versions become a query string. */
export function resolveMediaUrl(ref: MediaRef | string, options: { baseUrl?: string } = {}): string {
  const url = typeof ref === 'string' ? ref : ref.url;
  const version = typeof ref === 'string' ? undefined : ref.version;
  let resolved = url;
  if (url.startsWith('/') && options.baseUrl) resolved = options.baseUrl.replace(/\/+$/, '') + url;
  if (version) resolved += (resolved.includes('?') ? '&' : '?') + 'v=' + encodeURIComponent(version);
  return resolved;
}

export function mediaKindFor(url: string): MediaKind {
  if (/\.(mp4|webm|mov)(\?|$)/i.test(url)) return 'video';
  if (/\.(mp3|m4a|ogg|wav)(\?|$)/i.test(url)) return 'audio';
  return 'image';
}
