'use client';
import type { ReactNode } from 'react';
import { Icon } from './icons';
import { BackButton, LanguageSwitch, ProgressBar, ProgressRing } from './primitives';
import { MediaImage } from '../engine/media';
import { variantOf } from '../engine/registry';
import type { Locale, ResolvedMedia, ThemeSummary } from '../ui-types';

/** Top chrome of a Learn or Play session: back, explicit topic title, language. */
export function SessionBar({ locale, title, onBack, onLanguage, busy }: { locale: Locale; title: string; onBack: () => void; onLanguage: (locale: Locale) => void; busy: boolean }) {
  const el = locale === 'el';
  return <div className="session-bar">
    <BackButton onClick={onBack}><span className="sr-only">{el ? 'Πίσω στη θεματική' : 'Back to the theme'}</span></BackButton>
    <span className="session-title">{title}</span>
    <div className="session-bar-right"><LanguageSwitch className="only-mobile" locale={locale} onChange={onLanguage} busy={busy} /></div>
  </div>;
}

export function SessionProgress({ value, label, counter }: { value: number; label: string; counter: string }) {
  return <div className="session-progress"><ProgressBar value={value} label={label} /><span>{counter}</span></div>;
}

export function QuestionCard({ eyebrow, meta, prompt, children, actions, className = '' }: { eyebrow: ReactNode; meta?: ReactNode; prompt: string; children: ReactNode; actions?: ReactNode; className?: string }) {
  return <article className={`question-card ${className}`}>
    <div className="session-meta"><span className="eyebrow">{eyebrow}</span>{meta}</div>
    <h1 className="question-text">{prompt}</h1>
    {children}
    {actions && <div className="question-actions">{actions}</div>}
  </article>;
}

export function TimerRing({ seconds, limit, locale }: { seconds: number; limit: number; locale: Locale }) {
  const el = locale === 'el';
  const urgent = seconds <= 10;
  return <div className={`timer-ring ${urgent ? 'urgent' : ''}`} aria-live="off">
    <ProgressRing value={limit > 0 ? (seconds / limit) * 100 : 0} size={116} stroke={9} label={el ? `Απομένουν ${seconds} δευτερόλεπτα` : `${seconds} seconds remaining`}>
      <strong>{seconds}</strong><span>{el ? 'δευτερόλεπτα' : 'seconds'}</span>
    </ProgressRing>
  </div>;
}

/** Decorative scenery band (registry component "scenery") using the theme's scenery or cover art. */
export function Scenery({ theme, media }: { theme: Pick<ThemeSummary, 'components' | 'cover' | 'colors' | 'typography'> | null | undefined; media?: ResolvedMedia }) {
  if (!theme || variantOf(theme, 'scenery') === 'hidden') return null;
  return <div className="scenery" aria-hidden="true"><MediaImage media={media ?? theme.cover} alt="" loading="lazy" /></div>;
}

export function NoTimerPill({ locale }: { locale: Locale }) {
  return <span className="pill pill--orange"><Icon name="infinity" />{locale === 'el' ? 'Χωρίς χρόνο' : 'No timer'}</span>;
}
