'use client';
import { useEffect, useRef, useState } from 'react';
import { Icon } from './ui/icons';
import { createNarrationPlayer, loadAudio, type AudioFailure, type NarrationPlayer } from './engine/audio';
import { transportFetch, usePlayerTransport } from './engine/transport.ts';
import type { Locale } from './ui-types';
export type AudioItem = { label:string;url:string;segment:string };
// Runtime feature flag "audio": when an operator disables it, no playback control is rendered anywhere.
let audioFeatureEnabled = true;
export function setAudioFeatureEnabled(enabled: boolean) { audioFeatureEnabled = enabled; }
// Loading, validating, aborting and releasing a clip is `app/engine/audio.ts`; this renders a button.
const message=(failure:AudioFailure,el:boolean)=>failure==='unauthorized'
  ?(el?'Η σύνδεση έληξε. Συνδέσου ξανά.':'Your session has expired. Please sign in again.')
  :(el?'Δεν ήταν δυνατή η αναπαραγωγή. Δοκίμασε ξανά.':'Playback failed. Please try again.');
export function AudioControls({items=[],locale}:{items?:AudioItem[];locale:Locale}) {
  // `active` is the tap, `playing` is the sound. A clip arrives over the network, so between the two
  // there is a real wait, and the control has to follow `active`: otherwise it still reads "Listen"
  // while the first clip downloads and the next tap starts a second request instead of cancelling.
  const [active,setActive]=useState(false);const [playing,setPlaying]=useState(false);const [error,setError]=useState('');
  const player=useRef<NarrationPlayer|null>(null);
  // On a partner's page the clip is fetched through the host's transport; on LGU's own screens the loader keeps its own fetch.
  const transport=usePlayerTransport();
  const signature=items.map(i=>i.url).join('|');const el=locale==='el';
  useEffect(()=>{
    const instance=createNarrationPlayer({...(transport?{load:(path:string,init:{signal:AbortSignal})=>loadAudio(path,{...init,fetch:transportFetch(transport)})}:{}),onActiveChange:setActive,onPlayingChange:setPlaying,onFailure:failure=>setError(message(failure,el))});
    player.current=instance;
    const cancel=()=>instance.stop();
    window.addEventListener('lgu-stop-audio',cancel);
    // Unmount, a new question or a language change all end in the same place: the request is
    // aborted, the element is detached and the object URL is revoked.
    return()=>{window.removeEventListener('lgu-stop-audio',cancel);instance.stop();player.current=null;};
  },[signature,el,transport]);
  const stop=()=>{setError('');player.current?.stop();};
  const play=(list:AudioItem[])=>{setError('');window.dispatchEvent(new Event('lgu-stop-audio'));player.current?.play(list);};
  if(!items.length || !audioFeatureEnabled)return null;
  return <div className="audio-controls">
    <button className="btn btn-soft btn-sm" type="button" onClick={()=>active?stop():play(items)} aria-busy={active&&!playing} aria-label={active?(el?'Διακοπή ήχου':'Stop audio'):(el?'Άκουσε το κείμενο':'Listen to the text')}><Icon name={active?'stop':'volume'}/> {active?(el?'Διακοπή':'Stop'):(el?'Άκουσε':'Listen')}</button>
    {items.length>1 && <details><summary>{el?'Επίλεξε τι θα ακούσεις':'Choose what to hear'}</summary><div className="audio-segments">{items.map(item=><button type="button" key={item.segment} onClick={()=>play([item])} title={item.label}>▶ {item.label}</button>)}</div></details>}
    {error && <span role="status" className="note">{error}</span>}
  </div>;
}
