import { createElement } from 'react';
import { createRoot } from 'react-dom/client';
import { LivePlayer, type LivePlayerProps } from './live-player';

// The bundle a partner's page loads: `npm run player:build` → `dist/player/lgu-live-player.js`, with
// its stylesheet, its fonts and its types beside it (`docs/LIVE_PLAYER_SURFACE.md`).
//
// It carries React of its own, so it exposes a mount function and never a component: a component
// would have to share the host's React, and the bundle's is not the host's. A host that compiles
// LGU's source with its own React imports `app/player/index.ts` instead and gets the component.

export { proxyTransport, webTransport } from '../engine/transport.ts';
export { leaveLiveRoom } from './live-player';
export type { LivePlayerProps, PlayerError } from './live-player';
export type { PlayerTransport } from '../engine/transport.ts';
export type { LiveSessionView, Locale } from '../ui-types';

/** The LGU application version this bundle was built from. */
export const PLAYER_VERSION: string = process.env.NEXT_PUBLIC_LGU_APP_VERSION || '0.0.0';

export type MountedLivePlayer = {
  /** Re-renders with the given props changed; a new `sessionId` or `transport` reopens the room. */
  update(next: Partial<LivePlayerProps>): void;
  /** Unmounts the tree: the stream is closed and every object URL released. */
  unmount(): void;
};

/** Mounts the live player into an element the host owns — the main stage's content element, say — and hands back its controls. */
export function mountLivePlayer(element: Element, props: LivePlayerProps): MountedLivePlayer {
  const root = createRoot(element);
  let current = props;
  const render = () => root.render(createElement(LivePlayer, current));
  render();
  return {
    update(next) { current = { ...current, ...next }; render(); },
    unmount() { root.unmount(); },
  };
}
