'use client';
import { useCallback, useMemo, useRef, useState, type ReactNode } from 'react';
import { DragDropProvider, PointerSensor, type DragDropEventHandlers } from '@dnd-kit/react';
import { Accessibility, Feedback, PointerActivationConstraints, type DragDropManagerInput } from '@dnd-kit/dom';
import { isSortable } from '@dnd-kit/react/sortable';
import type { Locale } from '../ui-types';

// The drag and drop foundation the answer controls share: one configured pointer sensor, the screen
// reader announcements in the learner's language, the drop animation switched off with reduced motion,
// and a live region for what the keyboard and the tap-to-place flow do. The rules of a sequence and of a
// pairing are not here — app/engine/arrangement.ts holds them, and the two controls apply them.
//
// Modern dnd-kit line only (@dnd-kit/react 0.5.0 over @dnd-kit/dom): sensors are plugin descriptors,
// `useSortable` / `useDraggable` / `useDroppable` return ref callbacks, and the Feedback plugin lifts
// the dragged element into the top layer itself. Nothing from @dnd-kit/core or @dnd-kit/sortable.

/** What a card or a place says about itself, read back by the announcements. */
export type DragData = { label: string; position?: number };

/**
 * `handle`: the card is dragged by a dedicated grip, so the pointer means dragging the moment it moves
 * (a mouse starts at once; a finger or pen after four pixels — the grip itself blocks the browser's
 * own pan with `touch-action: none`, so nothing competes). `card`: the whole card is both a button and
 * a drag source, so a finger has to rest on it for 250 ms before a drag begins and a scroll gesture
 * (more than six pixels in that time) is left to the page; a mouse drags after five pixels, a mouse
 * that is held still does not, and a plain click stays a click. One constraint per pointer type: the
 * sensor's own default pairs a delay with a distance for the mouse, which this control does not need.
 */
export type Activation = 'handle' | 'card';

function pointerSensor(activation: Activation) {
  return PointerSensor.configure({
    activationConstraints(event) {
      const touch = event.pointerType === 'touch' || event.pointerType === 'pen';
      if (activation === 'handle') return touch ? [new PointerActivationConstraints.Distance({ value: 4 })] : undefined;
      if (touch) return [new PointerActivationConstraints.Delay({ value: 250, tolerance: 6 })];
      return [new PointerActivationConstraints.Distance({ value: 5 })];
    },
  });
}

/** Typographic quotes in the learner's language. */
export function quote(text: string, el: boolean) {
  return el ? `«${text}»` : `“${text}”`;
}

type Announcements = NonNullable<ConstructorParameters<typeof Accessibility>[1]>['announcements'];
type PluginsInput = NonNullable<DragDropManagerInput['plugins']>;

/** The sentences the drag itself speaks to a screen reader, from the data each card and place carries. */
function announcementsFor(locale: Locale, kind: 'order' | 'match'): NonNullable<Announcements> {
  const el = locale === 'el';
  const label = (entity: { data?: unknown } | null | undefined) => quote(((entity?.data as DragData | undefined)?.label) ?? '', el);
  return {
    dragstart({ operation: { source } }) {
      if (!source) return;
      return el ? `Σήκωσες ${label(source)}.` : `Picked up ${label(source)}.`;
    },
    dragover({ operation: { source, target } }) {
      if (!source) return;
      if (kind === 'order') {
        if (!isSortable(source)) return;
        return el ? `${label(source)} προς τη θέση ${source.index + 1}.` : `${label(source)} towards place ${source.index + 1}.`;
      }
      if (!target) return el ? `${label(source)} εκτός θέσης.` : `${label(source)} is over no place.`;
      return el ? `${label(source)} πάνω από ${label(target)}.` : `${label(source)} over ${label(target)}.`;
    },
    dragend({ operation: { source, target }, canceled }) {
      if (!source) return;
      if (canceled) return el ? `Ακυρώθηκε. ${label(source)} έμεινε όπου ήταν.` : `Cancelled. ${label(source)} stayed where it was.`;
      if (kind === 'order') {
        if (!isSortable(source)) return;
        return el ? `${label(source)} αφέθηκε στη θέση ${source.index + 1}.` : `${label(source)} dropped at place ${source.index + 1}.`;
      }
      if (!target) return el ? `${label(source)} αφέθηκε χωρίς θέση. Τίποτα δεν άλλαξε.` : `${label(source)} dropped on no place. Nothing changed.`;
      return el ? `${label(source)} αφέθηκε σε ${label(target)}.` : `${label(source)} dropped on ${label(target)}.`;
    },
  };
}

/** What a screen reader reads on a card or a grip: the keyboard is served by the controls' own buttons. */
export function dragInstructions(locale: Locale) {
  return locale === 'el'
    ? 'Σύρε την κάρτα με το ποντίκι ή με το δάχτυλο. Με το πληκτρολόγιο, χρησιμοποίησε τα κουμπιά της κάρτας.'
    : 'Drag the card with the mouse or a finger. With the keyboard, use the card’s buttons.';
}

type Handlers = Pick<DragDropEventHandlers, 'onDragStart' | 'onDragEnd'>;

/**
 * The provider every answer control renders once. The pointer is the only sensor: a learner who does
 * not drag uses real buttons, which keep their own names, their own focus and their own announcements
 * (and are what a remote control will press one day) — a second, keyboard-driven drag model on the
 * same elements would make every control answer two different ways to the same key.
 */
export function AnswerDragProvider({ locale, kind, reducedMotion, onDragStart, onDragEnd, children }: Handlers & {
  locale: Locale;
  kind: 'order' | 'match';
  reducedMotion: boolean;
  children: ReactNode;
}) {
  const sensors = useMemo(() => [pointerSensor(kind === 'order' ? 'handle' : 'card')], [kind]);
  const plugins = useMemo<PluginsInput>(() => defaults => [
    ...defaults,
    Accessibility.configure({ announcements: announcementsFor(locale, kind), screenReaderInstructions: { draggable: dragInstructions(locale) } }),
    Feedback.configure({ dropAnimation: reducedMotion ? null : undefined }),
  ], [locale, kind, reducedMotion]);
  return <DragDropProvider sensors={sensors} plugins={plugins} onDragStart={onDragStart} onDragEnd={onDragEnd}>{children}</DragDropProvider>;
}

/**
 * A polite live region for what the buttons do: a selection, a placement, a move, a cancellation. The
 * same sentence twice would be read once, so every message differs from the last by an invisible
 * character when it has to.
 */
export function useAnnouncer() {
  const [message, setMessage] = useState('');
  const turn = useRef(0);
  const announce = useCallback((text: string) => {
    turn.current += 1;
    setMessage(turn.current % 2 === 0 ? `${text}​` : text);
  }, []);
  const region = <span className="sr-only" role="status" aria-live="polite" aria-atomic="true">{message}</span>;
  return { announce, region };
}
