'use client';
import { useEffect, useRef, useState } from 'react';
import { useDraggable, useDroppable } from '@dnd-kit/react';
import { Icon } from './icons';
import { AnswerDragProvider, dragInstructions, quote, useAnnouncer, type DragData } from './dnd';
import { usePrefersReducedMotion } from './card-turn';
import { clearSlot, pairingFor, placeCard, slotOf, unplacedCards } from '../engine/arrangement.ts';
import type { DisplayQuestion, Locale, Question } from '../ui-types';

// The pairing a learner builds. Every left-hand item keeps a visible place beside it; the right-hand
// cards wait in one shared area below. A card is dragged onto a place — which lights up while it can
// take the card, whatever the answer — or tapped and then the place tapped. A card already placed can be
// dragged on, tapped on, sent back to the available answers, or pushed out by another card dropped on
// its place. Nothing here says whether a pair is right: the answer is the list of card ids per place
// that the API has always received, and the server marks it once, after submission.

type Where = 'pool' | 'slot';

export function MatchInput({ question, answer, setAnswer, busy, locale }: {
  question: DisplayQuestion;
  answer: string[];
  setAnswer: (answer: string[]) => void;
  busy: boolean;
  locale: Locale;
}) {
  const el = locale === 'el';
  const left = question.options;
  const right = question.rightOptions ?? [];
  const cardIds = right.map(option => option.id);
  const pairing = pairingFor(left.length, cardIds, answer);
  const pool = unplacedCards(pairing, cardIds);
  const textOf = (id: string) => right.find(option => option.id === id)?.text ?? '';
  const reduced = usePrefersReducedMotion();
  const { announce, region } = useAnnouncer();
  const [selected, setSelected] = useState<string | null>(null);
  const prefix = `match-${question.id}`;
  // A card moved by a tap is rendered in another container, which is a new DOM node: focus follows it.
  const refocus = useRef<string | null>(null);
  useEffect(() => {
    if (!refocus.current) return;
    const id = refocus.current;
    refocus.current = null;
    document.getElementById(`${prefix}-card-${id}`)?.focus();
  });
  useEffect(() => { if (busy) setSelected(null); }, [busy]);

  const place = (slot: number, cardId: string, via: 'drag' | 'tap') => {
    const displaced = pairing[slot] && pairing[slot] !== cardId ? pairing[slot] : '';
    setAnswer(placeCard(pairing, slot, cardId));
    setSelected(null);
    if (via === 'tap') refocus.current = cardId;
    announce((el ? `${quote(textOf(cardId), el)} τοποθετήθηκε στη θέση για ${quote(left[slot].text, el)}.` : `${quote(textOf(cardId), el)} placed beside ${quote(left[slot].text, el)}.`)
      + (displaced ? (el ? ` ${quote(textOf(displaced), el)} επέστρεψε στις διαθέσιμες.` : ` ${quote(textOf(displaced), el)} is available again.`) : ''));
  };
  const remove = (cardId: string, via: 'drag' | 'tap') => {
    const slot = slotOf(pairing, cardId);
    if (slot < 0) return;
    setAnswer(clearSlot(pairing, slot));
    setSelected(null);
    if (via === 'tap') refocus.current = cardId;
    announce(el ? `${quote(textOf(cardId), el)} επέστρεψε στις διαθέσιμες απαντήσεις.` : `${quote(textOf(cardId), el)} is back among the available answers.`);
  };
  // A tap on a card selects it; with another card already selected, a tap on a placed card puts the
  // selected one there instead — the same thing a drop on an occupied place does.
  const tapCard = (cardId: string) => {
    if (selected && selected !== cardId) {
      const slot = slotOf(pairing, cardId);
      if (slot >= 0) { place(slot, selected, 'tap'); return; }
    }
    if (selected === cardId) {
      setSelected(null);
      announce(el ? `${quote(textOf(cardId), el)} δεν είναι πια επιλεγμένη.` : `${quote(textOf(cardId), el)} is no longer selected.`);
      return;
    }
    setSelected(cardId);
    announce(el ? `Επιλέχθηκε ${quote(textOf(cardId), el)}. Πάτησε μια θέση για να την τοποθετήσεις, ή την κάρτα ξανά για αποεπιλογή.` : `Selected ${quote(textOf(cardId), el)}. Press a place to put it there, or the card again to deselect.`);
  };
  const tapEmptyPlace = (slot: number) => {
    if (selected) place(slot, selected, 'tap');
    else announce(el ? 'Διάλεξε πρώτα μια απάντηση από τις διαθέσιμες.' : 'Choose an answer from the available ones first.');
  };

  return <AnswerDragProvider locale={locale} kind="match" reducedMotion={reduced}
    onDragStart={() => setSelected(null)}
    onDragEnd={event => {
      if (event.canceled) return;
      const { source, target } = event.operation;
      const cardId = source && typeof source.id === 'string' && source.id.startsWith('card-') ? source.id.slice('card-'.length) : null;
      if (!cardId || !target) return;
      if (target.id === 'pool') remove(cardId, 'drag');
      else if (typeof target.id === 'string' && target.id.startsWith('slot-')) place(Number(target.id.slice('slot-'.length)), cardId, 'drag');
    }}>
    <div className="match-board">
      <p className="question-hint">{el ? 'Σύρε κάθε απάντηση στη θέση της, ή πάτησέ την και μετά πάτησε τη θέση.' : 'Drag each answer to its place, or tap it and then tap the place.'}</p>
      <ol className="match-list">{left.map((option, index) => <MatchPlace key={option.id} index={index} option={option} held={pairing[index]} heldText={textOf(pairing[index])} selected={selected} selectedText={selected ? textOf(selected) : ''} busy={busy} el={el} prefix={prefix}
        onTapCard={tapCard} onTapEmpty={() => tapEmptyPlace(index)} onRemove={() => remove(pairing[index], 'tap')} />)}</ol>
      <MatchPool ids={pool} textOf={textOf} selected={selected} busy={busy} el={el} prefix={prefix} onTapCard={tapCard} />
      <span id={`${prefix}-help`} className="sr-only">{dragInstructions(locale)} {el ? 'Enter επιλέγει την κάρτα· Enter σε μια θέση την τοποθετεί εκεί.' : 'Enter selects the card; Enter on a place puts it there.'}</span>
      {region}
    </div>
  </AnswerDragProvider>;
}

function MatchPlace({ index, option, held, heldText, selected, selectedText, busy, el, prefix, onTapCard, onTapEmpty, onRemove }: {
  index: number; option: Question['options'][number]; held: string; heldText: string; selected: string | null; selectedText: string; busy: boolean; el: boolean; prefix: string;
  onTapCard: (id: string) => void; onTapEmpty: () => void; onRemove: () => void;
}) {
  const { ref, isDropTarget } = useDroppable({ id: `slot-${index}`, type: 'slot', accept: 'card', disabled: busy, data: { label: option.text, position: index + 1 } satisfies DragData });
  const ready = !!selected && selected !== held;
  return <li className="match-row">
    <span className="match-left" id={`${prefix}-left-${index}`}>{option.text}</span>
    <div ref={ref} className={`match-slot ${held ? 'is-filled' : ''} ${isDropTarget ? 'is-over' : ''} ${ready ? 'is-ready' : ''}`}>
      {held
        ? <>
          {/* Keyed by the card: a place that changes hands gets a fresh card component, never one whose drag identity changes underneath it. */}
          <MatchCard key={held} id={held} text={heldText} where="slot" placeText={option.text} selected={selected === held} replaceWith={ready ? selectedText : ''} busy={busy} el={el} prefix={prefix} onTap={onTapCard} />
          <button type="button" className="match-remove" disabled={busy} onClick={onRemove}
            aria-label={el ? `Αφαίρεση «${heldText}» από τη θέση για «${option.text}»` : `Remove “${heldText}” from the place beside “${option.text}”`}><Icon name="x" /></button>
        </>
        : <button type="button" id={`${prefix}-place-${index}`} className="match-place" disabled={busy} onClick={onTapEmpty}
          aria-label={ready ? (el ? `Τοποθέτηση «${selectedText}» στη θέση για «${option.text}»` : `Put “${selectedText}” beside “${option.text}”`) : (el ? `Θέση για «${option.text}», κενή` : `Place beside “${option.text}”, empty`)}>
          {ready ? (el ? 'Τοποθέτηση εδώ' : 'Place here') : (el ? 'Σύρε ή επίλεξε απάντηση' : 'Drag or choose an answer')}
        </button>}
    </div>
  </li>;
}

function MatchPool({ ids, textOf, selected, busy, el, prefix, onTapCard }: {
  ids: string[]; textOf: (id: string) => string; selected: string | null; busy: boolean; el: boolean; prefix: string; onTapCard: (id: string) => void;
}) {
  const label = el ? 'Διαθέσιμες απαντήσεις' : 'Available answers';
  const { ref, isDropTarget } = useDroppable({ id: 'pool', type: 'pool', accept: 'card', disabled: busy, data: { label: el ? 'τις διαθέσιμες απαντήσεις' : 'the available answers' } satisfies DragData });
  return <div ref={ref} className={`match-pool ${isDropTarget ? 'is-over' : ''}`} role="group" aria-labelledby={`${prefix}-pool-title`}>
    <span id={`${prefix}-pool-title`} className="match-pool__title">{label}</span>
    <div className="match-pool__cards">
      {ids.map(id => <MatchCard key={id} id={id} text={textOf(id)} where="pool" selected={selected === id} busy={busy} el={el} prefix={prefix} onTap={onTapCard} />)}
      {ids.length === 0 && <span className="match-pool__empty">{el ? 'Όλες οι απαντήσεις έχουν τοποθετηθεί.' : 'Every answer has been placed.'}</span>}
    </div>
  </div>;
}

function MatchCard({ id, text, where, placeText = '', selected, replaceWith = '', busy, el, prefix, onTap }: {
  id: string; text: string; where: Where; placeText?: string; selected: boolean; replaceWith?: string; busy: boolean; el: boolean; prefix: string; onTap: (id: string) => void;
}) {
  const { ref, isDragSource } = useDraggable({ id: `card-${id}`, type: 'card', disabled: busy, data: { label: text } satisfies DragData });
  const name = where === 'pool'
    ? (el ? `«${text}», διαθέσιμη απάντηση` : `“${text}”, available answer`)
    : replaceWith
      ? (el ? `«${text}» στη θέση για «${placeText}». Πάτησε για να τοποθετήσεις εκεί την «${replaceWith}».` : `“${text}” beside “${placeText}”. Press to put “${replaceWith}” there instead.`)
      : (el ? `«${text}», στη θέση για «${placeText}»` : `“${text}”, beside “${placeText}”`);
  return <button ref={ref} type="button" id={`${prefix}-card-${id}`} className={`match-card ${selected ? 'is-selected' : ''} ${isDragSource ? 'is-dragging' : ''}`}
    aria-label={name} aria-current={selected ? 'true' : undefined} aria-roledescription={el ? 'κάρτα απάντησης' : 'answer card'} aria-describedby={`${prefix}-help`}
    disabled={busy} onClick={() => onTap(id)}>
    <Icon name="grip" className="match-card__grip" /><span className="match-card__text">{text}</span>
  </button>;
}
