// A live session's stream on the client. The server streams the session's log as Server-Sent
// Events from the last sequence number the client saw; the client applies each entry and asks for
// the full state again after any gap. `EventSource` cannot carry the Authorization header a packaged
// shell needs, so the stream is read with `fetch` and a body reader — the same transport as the
// narration loader — and reconnects from where it stopped with a small backoff.

// Specifiers carry their extension so the Node test runner can load this module as the bundler does
// (`tests/live-stream-client.test.ts`), the way `app/engine/media.tsx` and `app/engine/audio.ts` are imported.
import { API_PREFIX } from '../api.ts';
import { apiOrigin } from './api-origin.ts';
import { getPlatform } from '../platform/index.ts';
import { sessionRequestHeaders } from './session.ts';
import type { Locale, LiveLogEntry, LiveQuestionView, LiveSessionView } from '../ui-types';

export type LiveStreamStatus = 'connecting' | 'open' | 'reconnecting' | 'closed';
export type LiveStreamHandlers = {
  /** A log entry, in order. The `seq` of the last one delivered is where a reconnect resumes. */
  onEntry: (entry: LiveLogEntry) => void;
  /** The server's clock, from the greeting and every heartbeat: `serverTime - Date.now()` is the offset to apply to deadlines. */
  onServerTime?: (serverTime: number) => void;
  onStatus?: (status: LiveStreamStatus) => void;
};

/** Parses one SSE frame (the lines between two blank lines). */
export function parseFrame(frame: string): { event: string; data: string; id: number | null } | null {
  let event = 'message';
  let id: number | null = null;
  const data: string[] = [];
  for (const raw of frame.split('\n')) {
    const line = raw.endsWith('\r') ? raw.slice(0, -1) : raw;
    if (!line || line.startsWith(':')) continue;
    const colon = line.indexOf(':');
    const field = colon < 0 ? line : line.slice(0, colon);
    const value = colon < 0 ? '' : line.slice(colon + 1).replace(/^ /, '');
    if (field === 'event') event = value;
    else if (field === 'data') data.push(value);
    else if (field === 'id') { const parsed = Number(value); id = Number.isFinite(parsed) ? parsed : null; }
  }
  if (data.length === 0) return null;
  return { event, data: data.join('\n'), id };
}

/**
 * Opens the stream and keeps it open until the returned function is called. Backoff after a drop
 * starts at one second and grows to five; every reconnect resumes after the last entry delivered.
 */
export function openLiveStream(sessionId: string, locale: Locale, after: number, handlers: LiveStreamHandlers, options: { fetch?: typeof globalThis.fetch; backoffMs?: readonly number[] } = {}): () => void {
  const platform = getPlatform();
  const request: typeof globalThis.fetch = options.fetch ?? ((input, init) => globalThis.fetch(input, init));
  const backoff = options.backoffMs ?? [1000, 2000, 3000, 5000];
  let cursor = after;
  let closed = false;
  let attempt = 0;
  let controller: AbortController | null = null;
  let timer: ReturnType<typeof setTimeout> | null = null;
  const status = (value: LiveStreamStatus) => { if (!closed) handlers.onStatus?.(value); };

  const consume = async (body: ReadableStream<Uint8Array>) => {
    const reader = body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buffer += decoder.decode(value, { stream: true });
      let boundary: number;
      while ((boundary = buffer.search(/\r?\n\r?\n/)) >= 0) {
        const frame = buffer.slice(0, boundary);
        buffer = buffer.slice(boundary).replace(/^\r?\n\r?\n/, '');
        const parsed = parseFrame(frame);
        if (!parsed) continue;
        let data: any;
        try { data = JSON.parse(parsed.data); } catch { continue; }
        if (parsed.event === 'hello' || parsed.event === 'ping') { if (typeof data?.serverTime === 'number') handlers.onServerTime?.(data.serverTime); continue; }
        if (typeof data?.seq === 'number') {
          if (data.seq <= cursor) continue;
          cursor = data.seq;
          attempt = 0;
          handlers.onEntry(data as LiveLogEntry);
        }
      }
    }
  };

  const connect = async () => {
    if (closed) return;
    controller = new AbortController();
    status(attempt === 0 ? 'connecting' : 'reconnecting');
    try {
      // `cache: 'no-store'`: the stream must bypass the HTTP cache altogether, not merely not be kept.
      // Firefox serialises concurrent requests for one URL behind the first response still in
      // progress, and two tabs of one profile on the same session — the host's controls and the
      // audience screen on the projector — ask for exactly the same URL while the room is quiet. The
      // second stream then never received its headers until the first tab left (found 5 October
      // 2026, reproduced three ways in Firefox; Chromium and WebKit do not queue). Bypassing the
      // cache takes the request out of that queue; the response is never cacheable anyway.
      const response = await request(`${apiOrigin()}${API_PREFIX}live/${sessionId}/stream?after=${cursor}&lang=${encodeURIComponent(locale)}`, {
        method: 'GET', credentials: 'same-origin', cache: 'no-store', signal: controller.signal,
        headers: { 'X-LGU-Client': platform.clientHeader(), ...sessionRequestHeaders(platform), Accept: 'text/event-stream' },
      });
      // A session that no longer admits this viewer (404 / 403) or a signed-out session (401) is not
      // retried forever: the screen is told and decides.
      if (response.status === 401 || response.status === 403 || response.status === 404) { closed = true; handlers.onStatus?.('closed'); return; }
      if (!response.ok || !response.body) throw new Error(`stream ${response.status}`);
      status('open');
      await consume(response.body);
    } catch { /* dropped: reconnect below */ }
    if (closed) return;
    const delay = backoff[Math.min(attempt, backoff.length - 1)];
    attempt += 1;
    status('reconnecting');
    timer = setTimeout(() => { void connect(); }, delay);
  };
  void connect();
  return () => {
    closed = true;
    if (timer) clearTimeout(timer);
    controller?.abort();
    handlers.onStatus?.('closed');
  };
}

// The three rules every mount of the live room follows — LGU's own screens (`app/quiz-app.tsx`) and
// the player a partner's page mounts (`app/player/`) — written once, so that neither can drift from
// the other. None of them decides anything about the game: the server does, and these only say which
// of its answers stands, what an empty answer looks like, and what a log entry means for the state in hand.

/**
 * The state read that stands when two overlap (a command's and the stream's): the one describing an
 * earlier version never replaces a later one, so a stale response cannot move the screen backwards.
 */
export function newerLiveState(current: LiveSessionView | null, loaded: LiveSessionView): LiveSessionView {
  if (!current || current.id !== loaded.id) return loaded;
  if (current.phaseVersion > loaded.phaseVersion) return current;
  if (current.phaseVersion === loaded.phaseVersion && current.lastSeq > loaded.lastSeq) return current;
  return loaded;
}

/**
 * A fresh answer for a question, in the shape its kind expects: the ids in the order shown for
 * `order`, one empty place per left-hand option for `match`, nothing picked for every other kind.
 */
export function initialLiveAnswer(question: Pick<LiveQuestionView, 'kind' | 'options'> | null | undefined): string[] {
  if (!question) return [];
  if (question.kind === 'order') return question.options.map(option => option.id);
  if (question.kind === 'match') return question.options.map(() => '');
  return [];
}

/**
 * Who is looking at the live screen, which decides whether it shows anything personal. A `player` is a
 * participant of the room (`me`), and only a player is told their own result, or that they did not answer.
 * The `host` — the organiser, who runs the game and never plays it — and a `spectator` (the audience screen,
 * or an account that may watch without having joined) see the question, the public reveal and the ranking.
 * The server's own view decides it: `me` and `role` are read from the database on every request.
 */
export type LiveViewer = 'player' | 'host' | 'spectator';
export function liveViewer(session: Pick<LiveSessionView, 'role' | 'me'>, spectator = false): LiveViewer {
  if (spectator) return 'spectator';
  if (session.me !== null) return 'player';
  return session.role === 'host' ? 'host' : 'spectator';
}

/**
 * What a log entry does to the state in hand. An `answered` entry carries the counts and who answered
 * — nothing about correctness before the reveal — and is applied in place; every other entry means
 * the state must be read again, and for those this returns `null`.
 */
export function liveEntryPatch(entry: LiveLogEntry): ((current: LiveSessionView) => LiveSessionView) | null {
  if (entry.kind !== 'answered') return null;
  const payload = entry.payload as { participantId?: string; answered?: number; eligible?: number };
  return current => ({
    ...current,
    answered: payload.answered ?? current.answered,
    eligible: payload.eligible ?? current.eligible,
    participants: current.participants.map(p => p.participantId === payload.participantId ? { ...p, answered: true } : p),
  });
}
