import type { Locale } from './ui-types';
import { getPlatform } from './platform/index.ts';
import { apiOrigin } from './engine/api-origin.ts';
import { sessionRequestHeaders, setSessionToken } from './engine/session.ts';
import { connectionMessage } from './engine/errors.ts';
import { webTransport, type PlayerTransport } from './engine/transport.ts';

/** Every client request targets the versioned API; the unversioned path remains an alias on the server. */
export const API_PREFIX = '/api/v1/';

/**
 * The session outcome a bearer client reads from a response, if the response states one: `session:
 * null` ends the session, `session: { token }` is a credential just issued. Anything else called
 * `session` — a live room's state, a live session summary — is data and says nothing about the
 * credential, so it must never clear the one in hand.
 */
export function sessionOutcome(data: unknown): { token: string | null } | null {
  if (!data || typeof data !== 'object' || !('session' in data)) return null;
  const session = (data as { session: unknown }).session;
  if (session === null) return { token: null };
  if (session && typeof session === 'object' && typeof (session as { token?: unknown }).token === 'string') return { token: (session as { token: string }).token };
  return null;
}

export async function requestApi(path: string, locale: Locale, method = 'GET', payload?: unknown) {
  return requestApiVia(webTransport, path, locale, method, payload);
}

/**
 * The same request through a transport the caller chose (`app/engine/transport.ts`). `requestApi` is
 * this with LGU's own transport; the live player a partner's page mounts passes the host's. The path,
 * the headers, the body and the error convention are decided here once, whichever way the bytes go.
 */
export async function requestApiVia(transport: Pick<PlayerTransport, 'fetch'>, path: string, locale: Locale, method = 'GET', payload?: unknown) {
  const platform = getPlatform();
  // How this platform carries the session is the platform's business, not each caller's.
  const bearer = platform.sessionTransport === 'bearer';
  const separator = path.includes('?') ? '&' : '?';
  // `apiOrigin()` is the empty string in a browser, so this stays the same relative URL it always was.
  const response = await transport.fetch(`${apiOrigin()}${API_PREFIX}${path}${separator}lang=${encodeURIComponent(locale)}`, {
    method,
    // In a browser this attaches the HttpOnly session cookie. From a native shell the API is a
    // different origin, so it correctly attaches nothing and the Authorization header carries the
    // session instead — the cookie is never relaxed to make a cross-site request work.
    credentials: 'same-origin',
    headers: {
      'X-LGU-Client': platform.clientHeader(),
      // One definition of how the session travels, shared with the narration loader in
      // `app/engine/audio.ts`: on the web it adds nothing and the cookie above does the work.
      ...sessionRequestHeaders(platform),
      ...(method === 'GET' ? {} : { 'Content-Type': 'application/json', 'X-LGU-Request': '1' }),
    },
    ...(payload === undefined ? {} : { body: JSON.stringify(payload) }),
  });
  let data: any = null;
  try { data = await response.json(); } catch { data = {}; }
  // An answered request: the body carries a message the server wrote in this learner's language, so
  // it is marked as safe to display. `lguApi` is the only thing that grants that — a transport
  // failure never gets here and so can never be mistaken for a message meant for a child
  // (`app/engine/errors.ts`).
  if (!response.ok) throw Object.assign(new Error(data?.error ?? connectionMessage(locale)), { lguApi: true as const, status: response.status, code: data?.code, data });
  // The backend states the session outcome explicitly for a bearer client: a token when one is
  // issued, `null` when it is ended. Browsers never see this field — their cookie is set by the
  // response header and stays out of reach of scripts. A `session` that is neither (a live room's
  // state is one) is data, and leaves the credential alone.
  const outcome = bearer ? sessionOutcome(data) : null;
  if (outcome) await setSessionToken(platform, outcome.token);
  return data;
}
