'use client';
import { Icon } from './icons';
import { MediaImage } from '../engine/media';
import { revealSheet, type RevealMark, type RevealRow } from '../../src/domain/answer-reveal';
import type { DisplayQuestion, Locale } from '../ui-types';

// The intermediate side of the Learn card: the same question, the same picture below it and the same
// answers in the same places, now marked. It teaches nothing new — the detailed card that follows does
// that — it only answers "what did I pick, and what was right?" at a glance.

const LETTERS = { el: ['Α', 'Β', 'Γ', 'Δ', 'Ε', 'Ζ'], en: ['A', 'B', 'C', 'D', 'E', 'F'] };

/** `label` is read out where the row carries no visible tag of its own (ordered and paired formats). */
function Mark({ mark, letter, label }: { mark: RevealMark; letter?: string; label?: string }) {
  return <span className={`reveal-mark reveal-mark--${mark}`}>
    {mark === 'idle'
      ? <span aria-hidden="true">{letter}</span>
      : <><Icon name={mark === 'correct' ? 'check' : 'x'} />{label && <span className="sr-only">{label}</span>}</>}
  </span>;
}

/** Correctness is never carried by colour alone: every marked row also has an icon and a word. */
function Tag({ mark, el }: { mark: RevealMark; el: boolean }) {
  if (mark === 'idle') return null;
  return <span className={`reveal-tag reveal-tag--${mark}`}>
    {mark === 'correct' ? (el ? 'Σωστή απάντηση' : 'Correct answer') : (el ? 'Η απάντησή σου' : 'Your answer')}
  </span>;
}

export function AnswerReveal({ locale, eyebrow, question, correct, submitted, correctIds, solution, publicVerdict = false }: {
  locale: Locale;
  eyebrow: string;
  question: DisplayQuestion;
  /** The server's verdict for the whole answer, taken as given: nothing here re-marks anything. */
  correct: boolean;
  submitted: string[];
  correctIds: string[];
  solution: string;
  /** For someone who did not play the question (the live host): the right answer named, no «Σωστά!» addressed to them. */
  publicVerdict?: boolean;
}) {
  const el = locale === 'el';
  const sheet = revealSheet({ kind: question.kind, options: question.options, rightOptions: question.rightOptions, submitted, correctIds });
  const letters = el ? LETTERS.el : LETTERS.en;
  const row = (item: RevealRow, index: number) => {
    // Image answers never carried letters, so an unmarked row simply keeps its picture.
    if (question.kind === 'image') return <li key={item.id} className={`answer-option answer-option--${item.mark}`}>
      {/* Through the media loader, as on the question face: a bundled icon resolves against the
          deployed origin, a private theme's picture is fetched with the session. */}
      <MediaImage media={{ url: item.imageUrl ?? '', alt: item.text, kind: 'image' }} alt={item.text} />
      <span className="reveal-foot">{item.mark !== 'idle' && <Mark mark={item.mark} />}<Tag mark={item.mark} el={el} /></span>
    </li>;
    return <li key={item.id} className={`answer-option answer-option--${item.mark}`}>
      <Mark mark={item.mark} letter={letters[index]} />
      <span className="reveal-text">{item.text}</span>
      <Tag mark={item.mark} el={el} />
    </li>;
  };
  return <article className={`question-card answer-reveal answer-reveal--${correct ? 'correct' : 'wrong'}`}>
    <div className="session-meta">
      <span className="eyebrow">{eyebrow}</span>
      <span className="reveal-verdict" role="status">{publicVerdict
        ? <span className="pill pill--neutral"><Icon name="check" />{el ? 'Η σωστή απάντηση' : 'The correct answer'}</span>
        : correct
        ? <span className="pill pill--gold"><Icon name="check" />{el ? 'Σωστά!' : 'Correct!'}</span>
        : <span className="pill pill--neutral">{el ? 'Η σωστή απάντηση είναι…' : 'The correct answer is…'}</span>}
      </span>
    </div>
    <h1 className="question-text">{question.prompt}</h1>

    {sheet.layout === 'choice' && <ul className={`answers reveal-list ${question.kind === 'image' ? 'image-answers' : ''}`}>{sheet.rows.map(row)}</ul>}

    {sheet.layout === 'order' && <>
      <ol className="order-list reveal-list">{sheet.rows.map(item => <li key={item.id} className={`order-item answer-option--${item.mark}`}>
        <span className="order-index" aria-hidden="true">{item.position}</span>
        <span className="order-text">{item.text}</span>
        <Mark mark={item.mark} label={item.mark === 'correct' ? (el ? 'σωστή θέση' : 'right place') : (el ? 'λάθος θέση' : 'wrong place')} />
      </li>)}</ol>
      {!correct && <p className="solution reveal-solution"><strong>{el ? 'Σωστή σειρά:' : 'Correct order:'}</strong> {solution}</p>}
    </>}

    {sheet.layout === 'match' && <div className="match-list reveal-list">{sheet.rows.map(item => <div key={item.id} className={`match-row answer-option--${item.mark}`}>
      <span>{item.text}</span>
      <span className="reveal-pair">
        <Mark mark={item.mark} label={item.mark === 'correct' ? (el ? 'σωστή αντιστοίχιση' : 'right match') : (el ? 'λάθος αντιστοίχιση' : 'wrong match')} />
        <span className="reveal-text">{item.answer}
          {item.expected && <small className="reveal-expected">{el ? 'Σωστό: ' : 'Correct: '}{item.expected}</small>}
        </span>
      </span>
    </div>)}</div>}
  </article>;
}
