import type { DeclaredDevice, DeviceCapabilities, DeviceProfile, DeviceSignals } from './device.ts';
import { NO_BROWSER_SIGNALS, VIEWPORT_BREAKPOINTS, classifyDevice, deviceFeatures, sameProfile } from './device.ts';
import type { Platform } from './types.ts';

// The web Device Profile adapter: reads what browsers can state reliably — pointer and hover media
// queries, touch points, viewport size, connected gamepads — and never a user agent. Every global is
// resolved at call time, so importing this module on the server is safe and the server profile is the
// no-browser profile. The browser cannot tell a phone from a tablet from a desktop from a TV with any
// reliability, so it never declares a form factor; a native adapter does that.
//
// CAPACITOR PLUG-IN POINT: `createNativePlatform()` (future, app/platform/index.ts) builds its own
// DeviceCapabilities — typically `createWebDevice(platform, environment, () => declared)` with the
// runtime, form factor and input it learns from its plugins — and the rest of the application does
// not change.

/** The subset of `window` / `navigator` the adapter reads. Narrow on purpose so tests can inject a fake. */
export type MediaQueryLike = {
  matches: boolean;
  addEventListener?(type: 'change', listener: () => void): void;
  removeEventListener?(type: 'change', listener: () => void): void;
  /** Older WebKit only has the deprecated pair. */
  addListener?(listener: () => void): void;
  removeListener?(listener: () => void): void;
};
export type WindowLike = {
  innerWidth?: number;
  innerHeight?: number;
  matchMedia?(query: string): MediaQueryLike;
  addEventListener?(type: string, listener: () => void): void;
  removeEventListener?(type: string, listener: () => void): void;
};
export type NavigatorLike = {
  maxTouchPoints?: number;
  getGamepads?(): ArrayLike<unknown | null>;
};
export type BrowserEnvironment = { window?: WindowLike; navigator?: NavigatorLike };

/** Globals, read now — never at import time. `window` decides "browser"; Node ships a `navigator`. */
export function globalEnvironment(): BrowserEnvironment {
  return {
    window: typeof window === 'undefined' || typeof document === 'undefined' ? undefined : (window as WindowLike),
    navigator: typeof navigator === 'undefined' ? undefined : (navigator as NavigatorLike),
  };
}

function query(win: WindowLike, media: string): boolean | null {
  try { const list = win.matchMedia?.(media); return list ? !!list.matches : null; } catch { return null; }
}

function count(value: unknown): number | null {
  return typeof value === 'number' && Number.isFinite(value) && value >= 0 ? value : null;
}

function gamepadCount(nav: NavigatorLike | undefined): number | null {
  if (!nav || typeof nav.getGamepads !== 'function') return null;
  try { const pads = nav.getGamepads(); let connected = 0; for (let index = 0; index < pads.length; index++) if (pads[index]) connected++; return connected; } catch { return null; }
}

export function readBrowserSignals(environment: BrowserEnvironment = globalEnvironment()): DeviceSignals {
  const win = environment.window;
  if (!win) return NO_BROWSER_SIGNALS;
  return {
    browser: true,
    viewportWidth: count(win.innerWidth),
    viewportHeight: count(win.innerHeight),
    maxTouchPoints: count(environment.navigator?.maxTouchPoints),
    pointerCoarse: query(win, '(pointer: coarse)'),
    pointerFine: query(win, '(pointer: fine)'),
    pointerNone: query(win, '(pointer: none)'),
    anyPointerCoarse: query(win, '(any-pointer: coarse)'),
    anyPointerFine: query(win, '(any-pointer: fine)'),
    hover: query(win, '(hover: hover)'),
    gamepads: gamepadCount(environment.navigator),
  };
}

/** Media queries whose transitions can change the profile. Width queries fire only when a size class
 * boundary is crossed, which is cheaper and quieter than listening to every resize. */
export const WATCHED_QUERIES: readonly string[] = [
  '(pointer: coarse)', '(pointer: fine)', '(pointer: none)', '(any-pointer: coarse)', '(any-pointer: fine)', '(hover: hover)',
  `(min-width: ${VIEWPORT_BREAKPOINTS.medium}px)`, `(min-width: ${VIEWPORT_BREAKPOINTS.expanded}px)`,
];
const WATCHED_EVENTS: readonly string[] = ['gamepadconnected', 'gamepaddisconnected'];

function watchQuery(list: MediaQueryLike, listener: () => void): () => void {
  if (typeof list.addEventListener === 'function') { list.addEventListener('change', listener); return () => list.removeEventListener?.('change', listener); }
  if (typeof list.addListener === 'function') { list.addListener(listener); return () => list.removeListener?.(listener); }
  return () => {};
}

/**
 * Builds `Platform.device` for a browser. `platform` is read lazily because the feature view is
 * derived from the platform's own capability adapters; `declared` lets a shell that wraps a WebView
 * (the Capacitor phase) supply authoritative runtime / form factor / input values while reusing the
 * same browser signal reading.
 */
export function createWebDevice(platform: () => Platform, environment?: BrowserEnvironment, declared?: () => DeclaredDevice | undefined): DeviceCapabilities {
  const env = () => environment ?? globalEnvironment();
  const listeners = new Set<(profile: DeviceProfile) => void>();
  let cached: DeviceProfile | null = null;
  let detach: (() => void) | null = null;

  const profile = (): DeviceProfile => {
    const next = classifyDevice(readBrowserSignals(env()), declared?.(), deviceFeatures(platform()));
    if (cached && sameProfile(cached, next)) return cached;
    cached = next;
    return next;
  };

  const notify = () => {
    const before = cached;
    const now = profile();
    if (now === before) return;
    for (const listener of listeners) listener(now);
  };

  const attach = (): (() => void) => {
    const win = env().window;
    if (!win) return () => {};
    const stops: (() => void)[] = [];
    for (const media of WATCHED_QUERIES) {
      let list: MediaQueryLike | undefined;
      try { list = win.matchMedia?.(media); } catch { list = undefined; }
      if (list) stops.push(watchQuery(list, notify));
    }
    for (const event of WATCHED_EVENTS) {
      if (typeof win.addEventListener !== 'function') break;
      win.addEventListener(event, notify);
      stops.push(() => win.removeEventListener?.(event, notify));
    }
    return () => { for (const stop of stops) stop(); };
  };

  return {
    profile,
    onChange(listener) {
      listeners.add(listener);
      if (listeners.size === 1) { profile(); detach = attach(); }
      let active = true;
      return () => {
        if (!active) return;
        active = false;
        listeners.delete(listener);
        if (listeners.size === 0 && detach) { detach(); detach = null; }
      };
    },
  };
}
