'use client';
import { useEffect, useRef, useState, type FocusEvent, type KeyboardEvent } from 'react';
import { isSortable, useSortable } from '@dnd-kit/react/sortable';
import { Icon } from './icons';
import { AnswerDragProvider, dragInstructions, quote, useAnnouncer } from './dnd';
import { usePrefersReducedMotion } from './card-turn';
import { moveItem } from '../engine/arrangement.ts';
import { orderingFor } from '../engine/ordering.ts';
import type { DisplayQuestion, Locale } from '../ui-types';

// The sequence a learner arranges. Each card is a sortable item: dragged by its grip, the other cards
// slide out of its way and a dashed outline shows the place it will take; released, it settles there
// and the arrangement becomes the answer — the same list of ids the API has always received. Without
// a drag the arrows move a card one place, and the grip itself is a keyboard control: Enter or Space
// picks the card up, the arrow keys carry it, Enter sets it down, Escape puts it back where it was.

/** A card picked up by the keyboard, with the sequence to restore if the learner changes their mind. */
type Grab = { id: string; from: string[] } | null;
type Control = 'grip' | 'up' | 'down';

export function OrderInput({ question, answer, setAnswer, busy, locale }: {
  question: DisplayQuestion;
  answer: string[];
  setAnswer: (answer: string[]) => void;
  busy: boolean;
  locale: Locale;
}) {
  const el = locale === 'el';
  const ids = orderingFor(question.options.map(option => option.id), answer);
  const textOf = (id: string) => question.options.find(option => option.id === id)?.text ?? '';
  const reduced = usePrefersReducedMotion();
  const { announce, region } = useAnnouncer();
  const [grab, setGrab] = useState<Grab>(null);
  const prefix = `order-${question.id}`;
  // What is true now, for a decision taken a moment after an event (see onCardBlur).
  const latest = useRef({ ids, grab });
  latest.current = { ids, grab };
  // A moved card is a DOM node moved, and a moved node loses its focus: the control that was used is
  // focused again once the new sequence is on screen.
  const refocus = useRef<{ id: string; control: Control } | null>(null);
  useEffect(() => {
    if (!refocus.current) return;
    const { id, control } = refocus.current;
    refocus.current = null;
    document.getElementById(`${prefix}-${control}-${id}`)?.focus();
  });
  useEffect(() => { if (busy) setGrab(null); }, [busy]);

  const place = (index: number) => el ? `θέση ${index + 1} από ${ids.length}` : `place ${index + 1} of ${ids.length}`;
  const move = (id: string, from: number, to: number, control: Control) => {
    if (to < 0 || to >= ids.length || from === to) return;
    setAnswer(moveItem(ids, from, to));
    refocus.current = { id, control };
    announce(el ? `${quote(textOf(id), el)} στη ${place(to)}.` : `${quote(textOf(id), el)} in ${place(to)}.`);
  };
  const pickUp = (id: string, index: number) => {
    setGrab({ id, from: ids });
    announce(el
      ? `Σήκωσες ${quote(textOf(id), el)} από τη ${place(index)}. Βελάκια πάνω και κάτω τη μετακινούν, Enter την αφήνει, Escape ακυρώνει.`
      : `Picked up ${quote(textOf(id), el)} from ${place(index)}. Arrow up and down move it, Enter sets it down, Escape cancels.`);
  };
  const setDown = (id: string, index: number) => {
    setGrab(null);
    announce(el ? `Άφησες ${quote(textOf(id), el)} στη ${place(index)}.` : `Set down ${quote(textOf(id), el)} in ${place(index)}.`);
  };
  const cancel = (grabbed: NonNullable<Grab>) => {
    const home = grabbed.from.indexOf(grabbed.id);
    setGrab(null);
    setAnswer(grabbed.from);
    refocus.current = { id: grabbed.id, control: 'grip' };
    announce(el ? `Ακυρώθηκε. ${quote(textOf(grabbed.id), el)} επέστρεψε στη ${place(home)}.` : `Cancelled. ${quote(textOf(grabbed.id), el)} is back in ${place(home)}.`);
  };
  const onGripKey = (event: KeyboardEvent<HTMLButtonElement>, id: string, index: number) => {
    if (busy) return;
    const grabbed = grab?.id === id;
    if (event.key === 'Enter' || event.key === ' ') {
      event.preventDefault();
      if (grabbed) setDown(id, index); else pickUp(id, index);
      return;
    }
    if (!grabbed || !grab) return;
    if (event.key === 'ArrowUp' || event.key === 'ArrowDown') { event.preventDefault(); move(id, index, index + (event.key === 'ArrowUp' ? -1 : 1), 'grip'); }
    else if (event.key === 'Home') { event.preventDefault(); move(id, index, 0, 'grip'); }
    else if (event.key === 'End') { event.preventDefault(); move(id, index, ids.length - 1, 'grip'); }
    else if (event.key === 'Escape') { event.preventDefault(); cancel(grab); }
  };
  // Focus that leaves the card while it is picked up sets it down where it is — like letting go. The
  // card is the unit, not the grip: a learner may Tab from the grip to an arrow, move the card with it,
  // and only then leave, and the pick-up must end there, where the card now is — otherwise a later
  // Escape would put back a sequence that no longer exists. Focus that goes to no element at all
  // (a click on the page, or the card's own node moved by a keyboard move and about to be focused
  // again) is judged a moment later, by where focus actually is.
  const onCardBlur = (event: FocusEvent<HTMLLIElement>, id: string) => {
    if (grab?.id !== id) return;
    const card = event.currentTarget;
    const leave = () => {
      const now = latest.current;
      if (now.grab?.id === id) setDown(id, now.ids.indexOf(id));
    };
    if (event.relatedTarget) { if (!card.contains(event.relatedTarget)) leave(); return; }
    setTimeout(() => { if (!card.contains(document.activeElement)) leave(); }, 0);
  };

  return <AnswerDragProvider locale={locale} kind="order" reducedMotion={reduced}
    onDragStart={() => setGrab(null)}
    onDragEnd={event => {
      if (event.canceled) return;
      const { source } = event.operation;
      // The sortable plugin has already carried the card to its place on screen; the answer follows it.
      if (isSortable(source) && source.initialIndex !== source.index) setAnswer(moveItem(ids, source.initialIndex, source.index));
    }}>
    <p className="question-hint">{el ? 'Σύρε τις κάρτες από τη λαβή τους, ή χρησιμοποίησε τα βελάκια.' : 'Drag the cards by their handle, or use the arrow buttons.'}</p>
    <ol className="order-list">{ids.map((id, index) => <OrderCard key={id} id={id} index={index} count={ids.length} text={textOf(id)} busy={busy} grabbed={grab?.id === id} reduced={reduced} el={el} prefix={prefix}
      onKeyDown={event => onGripKey(event, id, index)} onBlur={event => onCardBlur(event, id)}
      onUp={() => move(id, index, index - 1, 'up')} onDown={() => move(id, index, index + 1, 'down')} />)}</ol>
    <span id={`${prefix}-help`} className="sr-only">{dragInstructions(locale)} {el ? 'Enter ή Space σηκώνει την κάρτα, τα βελάκια πάνω και κάτω τη μετακινούν, Enter την αφήνει, Escape ακυρώνει.' : 'Enter or Space picks the card up, arrow up and down move it, Enter sets it down, Escape cancels.'}</span>
    {region}
  </AnswerDragProvider>;
}

function OrderCard({ id, index, count, text, busy, grabbed, reduced, el, prefix, onKeyDown, onBlur, onUp, onDown }: {
  id: string; index: number; count: number; text: string; busy: boolean; grabbed: boolean; reduced: boolean; el: boolean; prefix: string;
  onKeyDown: (event: KeyboardEvent<HTMLButtonElement>) => void;
  /** Focus leaving any of the card's controls — the grip or an arrow — reaches the card itself. */
  onBlur: (event: FocusEvent<HTMLLIElement>) => void;
  onUp: () => void;
  onDown: () => void;
}) {
  const { ref, handleRef, isDragSource } = useSortable({
    id, index, type: 'step', accept: 'step', disabled: busy,
    data: { label: text, position: index + 1 },
    // Reduced motion: the other cards take their new places at once instead of sliding.
    transition: reduced ? { duration: 0 } : undefined,
  });
  return <li ref={ref} className={`order-item ${isDragSource ? 'is-dragging' : ''} ${grabbed ? 'is-grabbed' : ''}`} onBlur={onBlur}>
    <span className="order-index" aria-hidden="true">{index + 1}</span>
    <span className="order-text" id={`${prefix}-text-${id}`}>{text}</span>
    <button ref={handleRef} type="button" id={`${prefix}-grip-${id}`} className="order-grip"
      aria-label={el ? `Μετακίνηση «${text}», θέση ${index + 1} από ${count}` : `Move “${text}”, place ${index + 1} of ${count}`}
      aria-roledescription={el ? 'λαβή μετακίνησης' : 'drag handle'} aria-describedby={`${prefix}-help`}
      data-grabbed={grabbed || undefined} disabled={busy} onKeyDown={onKeyDown}><Icon name="grip" /></button>
    <button type="button" id={`${prefix}-up-${id}`} className="order-step" aria-label={el ? `Μετακίνηση ${index + 1} πάνω` : `Move item ${index + 1} up`} disabled={index === 0 || busy} onClick={onUp}><Icon name="chevron-up" /></button>
    <button type="button" id={`${prefix}-down-${id}`} className="order-step" aria-label={el ? `Μετακίνηση ${index + 1} κάτω` : `Move item ${index + 1} down`} disabled={index === count - 1 || busy} onClick={onDown}><Icon name="chevron-down" /></button>
  </li>;
}
