'use client';
import { useEffect, useState, type ImgHTMLAttributes } from 'react';
import type { ResolvedMedia } from '../../src/domain/theme';
import { MEDIA_FALLBACK } from '../../src/domain/media';
import { assetUrl } from './api-origin.ts';
import { getPlatform } from '../platform/index.ts';
import { sessionRequestHeaders } from './session.ts';
import { transportFetch, usePlayerTransport, type PlayerTransport } from './transport.ts';

// Media loader: every theme image goes through here so a missing or failed asset degrades to a neutral
// placeholder instead of a broken image, and the failure can be reported as a technical event.
//
// Two kinds of image reach this component.
//
// *Public* artwork lives under `/learning-assets/`, `/question-assets/` or `/brand/` and is served as
// a static file. The element fetches it itself, exactly as it always has.
//
// *Private* artwork lives under `/media/<topic>/<file>` and belongs to a theme that is deliberately
// not in the public catalogue. The server only hands it to an account that may open that theme, which
// means the request must carry the session — and an `<img>` element cannot be given a header. On the
// web the session is an HttpOnly cookie the element would attach by itself, but a packaged shell
// serves its UI from the device and holds a bearer token instead, so the same reference would load in
// a browser and fail silently in the shell. This module therefore fetches private media the same way
// `app/engine/audio.ts` fetches narration: once, with the session, into an object URL the element can
// use. One rule, both platforms, and the credential never appears in a URL.

let reporter: ((url: string) => void) | null = null;
export function setMediaFailureReporter(fn: ((url: string) => void) | null) { reporter = fn; }

/** Whether a reference is a private theme file rather than a bundled one. Query strings are ignored. */
export function isPrivateMedia(url: string | null | undefined): boolean {
  return typeof url === 'string' && url.split('?')[0].startsWith('/media/');
}

type Fetcher = typeof globalThis.fetch;
let overrideFetch: Fetcher | null = null;
/** Tests drive the private path without a network. `null` restores the platform fetch. */
export function setMediaFetch(fn: Fetcher | null) { overrideFetch = fn; }

/**
 * Fetches one private file with the current session and returns an object URL for it.
 * Anything other than a real image is a failure, so an HTML error page never renders as a broken img.
 */
async function loadPrivateMedia(path: string, signal: AbortSignal, transport: PlayerTransport | null): Promise<string> {
  // A player mounted on a partner's page reaches LGU through the host's transport (`./transport.ts`);
  // LGU's own screens keep the browser's fetch, or the test seam, exactly as before.
  const request: Fetcher = transport ? transportFetch(transport) : overrideFetch ?? ((input, init) => globalThis.fetch(input, init));
  const platform = getPlatform();
  const response = await request(assetUrl(path), {
    method: 'GET',
    credentials: 'same-origin',
    headers: { 'X-LGU-Client': platform.clientHeader(), ...sessionRequestHeaders(platform) },
    signal,
  });
  if (!response.ok) throw new Error('MEDIA_UNAVAILABLE');
  const type = (response.headers.get('content-type') ?? '').split(';')[0].trim().toLowerCase();
  if (!type.startsWith('image/')) throw new Error('MEDIA_NOT_IMAGE');
  const blob = await response.blob();
  if (!blob.size) throw new Error('MEDIA_EMPTY');
  if (signal.aborted) throw new Error('MEDIA_ABORTED');
  return URL.createObjectURL(blob);
}

export function MediaImage({ media, fallbackSrc = MEDIA_FALLBACK.image, className, alt, ...rest }: { media: ResolvedMedia | null | undefined; fallbackSrc?: string } & Omit<ImgHTMLAttributes<HTMLImageElement>, 'src'>) {
  const [failed, setFailed] = useState(false);
  const [objectUrl, setObjectUrl] = useState<string | null>(null);
  const transport = usePlayerTransport();
  const reference = media?.url ?? '';
  const priv = isPrivateMedia(reference);

  useEffect(() => {
    setFailed(false);
    setObjectUrl(null);
    if (!priv || !reference) return;
    const controller = new AbortController();
    let created: string | null = null;
    let cancelled = false;
    loadPrivateMedia(reference, controller.signal, transport).then(url => {
      // Signing out, moving on or replacing the image mid-flight: create nothing that outlives it.
      if (cancelled) { URL.revokeObjectURL(url); return; }
      created = url;
      setObjectUrl(url);
    }).catch(() => { if (!cancelled) { setFailed(true); reporter?.(reference); } });
    return () => {
      cancelled = true;
      controller.abort();
      if (created) URL.revokeObjectURL(created);
    };
  }, [reference, priv, transport]);

  // Root-relative public media is served by the deployed origin, so a packaged shell resolves the same
  // reference the browser does without carrying a copy of the artwork (app/engine/api-origin.ts).
  // While a private file is still being fetched the neutral mark stands in for it, but it is not a
  // failure yet, so it does not carry the failure class a stylesheet or a test keys on.
  const broken = failed || !reference;
  const pending = priv && !objectUrl && !broken;
  // A public file's address is the host's to give when a transport is installed; otherwise the deployed origin's, as always.
  const src = objectUrl ?? (transport ? transport.assetUrl : assetUrl)(broken || pending ? fallbackSrc : reference);
  // Controlled cropping, when the reference declares it: `contain` shows the whole picture inside the
  // frame, and a focus point keeps the part that matters in view when the frame crops the rest. A
  // reference without either renders exactly as it always has.
  const placement = media?.fit || media?.focus ? {
    ...(media.fit ? { objectFit: media.fit } : {}),
    ...(media.focus ? { objectPosition: `${Math.round(media.focus.x * 100)}% ${Math.round(media.focus.y * 100)}%` } : {}),
  } : null;
  return <img
    {...rest}
    {...(placement ? { style: { ...(rest.style ?? {}), ...placement } } : {})}
    className={[className, broken ? 'media-fallback' : ''].filter(Boolean).join(' ') || undefined}
    src={src}
    alt={alt ?? media?.alt ?? ''}
    {...(pending ? { 'data-media-pending': 'true' } : {})}
    onError={() => { if (!failed && reference && !priv) { setFailed(true); reporter?.(reference); } }}
  />;
}
