'use client';
import { useCallback, useEffect, useRef, useState } from 'react';
import { requestApiVia } from '../api.ts';
import { setAudioFeatureEnabled } from '../audio-controls';
import { isApiError, learnerMessage } from '../engine/errors.ts';
import { initialLiveAnswer, liveEntryPatch, newerLiveState, openLiveStream, type LiveStreamStatus } from '../engine/live.ts';
import { PlayerTransportProvider, transportFetch, type PlayerTransport } from '../engine/transport.ts';
import { LivePlayScreen } from '../screens/live-play-screen';
import { Alert } from '../ui/primitives';
import type { LiveSessionView, Locale } from '../ui-types';

// The live player as a surface another page may mount.
//
// This is the participant's live screen exactly as LGU's own site and shells show it —
// `LivePlayScreen` with the shared answer controls, the timer, the reveal and the ranking — with the
// one thing a foreign page cannot supply taken as a prop: how the network is reached
// (`app/engine/transport.ts`). The room is driven the way `app/quiz-app.tsx` drives it: read the
// state, follow the session's log, read again when the log says so, submit an answer, show the
// receipt until the reveal. The three rules the two mounts share are in `app/engine/live.ts`; what is
// here is the wiring of one React tree, and nothing about the game — the server decides every step.
//
// No renderer is written twice. `app/screens/live-play-screen.tsx` is the one live screen, this file
// imports it, and `tests/browser/player-surface.spec.ts` shows it playing a real published question on
// a page that is not LGU's origin and holds no LGU cookie.

/** An error the player reports to its host: the server's own code and status when the API answered, the localised message in every case. */
export type PlayerError = { status: number | null; code: string | null; message: string };

export type LivePlayerProps = {
  /** The live session to join the room of. Entering it — the federated door, the code, the event screen — is the host's business before mounting. */
  sessionId: string;
  locale: Locale;
  /** Where every request goes. `webTransport` on LGU's own pages; a host's own on a partner's page. */
  transport: PlayerTransport;
  /** The audience view: the same screen with nothing personal and nothing to press. What it shows is what the transport's credential may read. */
  spectator?: boolean;
  /** The narration controls beside a question that has clips. On by default, as on LGU's screens while the audio feature is on. */
  audio?: boolean;
  /** «Έξοδος» in the room, «Τέλος» after the game: the host decides what leaving means on its page. Without it the screen shows no way out. */
  onLeave?: () => void;
  /** Every state the player shows, as the server described it. */
  onSession?: (session: LiveSessionView) => void;
  onConnection?: (status: LiveStreamStatus) => void;
  onError?: (error: PlayerError) => void;
  /** Added to the player's outer element, for the host's own layout. */
  className?: string;
};

const playerError = (caught: unknown, locale: Locale): PlayerError => ({
  status: isApiError(caught) ? caught.status : null,
  code: isApiError(caught) && typeof caught.code === 'string' ? caught.code : null,
  message: learnerMessage(caught, locale),
});

/**
 * The room as one React tree lives it. The state the server last described, the server clock's
 * offset, the stream's status, the answer being composed, and the one request in flight.
 */
export function useLiveRoom({ sessionId, locale, transport, onError, onSession }: Pick<LivePlayerProps, 'sessionId' | 'locale' | 'transport' | 'onError' | 'onSession'>) {
  const [session, setSession] = useState<LiveSessionView | null>(null);
  const [offset, setOffset] = useState(0);
  const [connection, setConnection] = useState<LiveStreamStatus>('closed');
  const [answer, setAnswer] = useState<string[]>([]);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // The callbacks are read through refs so a host that passes a new function on every render does not reopen the stream.
  const callbacks = useRef({ onError, onSession });
  callbacks.current = { onError, onSession };

  const report = useCallback((caught: unknown) => { callbacks.current.onError?.(playerError(caught, locale)); }, [locale]);
  const load = useCallback(async () => {
    const loaded = (await requestApiVia(transport, `live/${sessionId}`, locale)).session as LiveSessionView;
    // Two reads may overlap (an answer's and the stream's); the one describing an earlier version never replaces a later one.
    setSession(current => newerLiveState(current, loaded));
    setOffset(loaded.serverTime - Date.now());
    return loaded;
  }, [transport, sessionId, locale]);

  // The state first, then the session's log from the sequence that state carried; a reconnect resumes
  // after the last entry delivered. Nothing here advances the session: the host's commands and the
  // server's clock do, and the log says when to read again.
  useEffect(() => {
    let stopped = false;
    let stop: (() => void) | null = null;
    let reloading = false;
    let again = false;
    const reload = async () => {
      if (reloading) { again = true; return; }
      reloading = true;
      try { do { again = false; await load(); } while (again); }
      catch (caught) { report(caught); /* the next entry, or the next reconnect, reads again */ }
      finally { reloading = false; }
    };
    setSession(null); setError(null); setConnection('connecting');
    load().then(loaded => {
      if (stopped) return;
      stop = openLiveStream(sessionId, locale, loaded.lastSeq, {
        onEntry: entry => {
          // Counts travel on an `answered` entry itself; nothing about correctness does before the reveal. Every other entry is read again.
          const patch = liveEntryPatch(entry);
          if (patch) { setSession(current => current && current.id === sessionId ? patch(current) : current); return; }
          void reload();
        },
        onServerTime: serverTime => setOffset(serverTime - Date.now()),
        onStatus: setConnection,
      }, { fetch: transportFetch(transport) });
    }).catch(caught => {
      if (stopped) return;
      setConnection('closed');
      setError(learnerMessage(caught, locale));
      report(caught);
    });
    return () => { stopped = true; stop?.(); };
  }, [sessionId, locale, transport, load, report]);

  // A fresh answer for every question, in the shape its kind expects.
  useEffect(() => { setAnswer(initialLiveAnswer(session?.question)); }, [session?.id, session?.questionIndex]);
  useEffect(() => { if (session) callbacks.current.onSession?.(session); }, [session]);

  const submit = useCallback(() => {
    if (!session?.question || busy) return;
    const submitted = answer;
    const id = session.id;
    setBusy(true); setError(null);
    requestApiVia(transport, `live/${id}/answer`, locale, 'POST', { questionIndex: session.question.index, phaseVersion: session.phaseVersion, answer: submitted })
      // The receipt is shown at once; how it scored arrives with the reveal.
      .then(result => setSession(current => current && current.id === id ? { ...current, own: { submitted, correct: false, points: 0, elapsedMs: Number(result.elapsedMs) || 0, late: false } } : current))
      .catch(caught => { setError(learnerMessage(caught, locale)); report(caught); })
      .finally(() => setBusy(false));
  }, [session, busy, answer, transport, locale, report]);

  return { session, offset, connection, answer, setAnswer, busy, error, dismiss: () => setError(null), submit };
}

/** Leaving on purpose, the way LGU's own screen does it: the room's credential is ended on the server. A host calls it from `onLeave` when that is what leaving means on its page. */
export function leaveLiveRoom(transport: PlayerTransport, sessionId: string, locale: Locale): Promise<{ left: boolean }> {
  return requestApiVia(transport, `live/${sessionId}/leave`, locale, 'POST', {});
}

export function LivePlayer({ sessionId, locale, transport, spectator = false, audio = true, onLeave, onSession, onConnection, onError, className }: LivePlayerProps) {
  const room = useLiveRoom({ sessionId, locale, transport, onError, onSession });
  useEffect(() => { setAudioFeatureEnabled(audio); }, [audio]);
  const connectionCallback = useRef(onConnection);
  connectionCallback.current = onConnection;
  useEffect(() => { connectionCallback.current?.(room.connection); }, [room.connection]);
  const el = locale === 'el';
  // Two elements on purpose: the outer one is the container the stylesheet's width queries measure
  // (`scripts/player-build.mjs` turns them into container queries), the inner one carries the tokens
  // and the base styles that `:root` and `body` carry on LGU's own page — a container cannot query itself.
  return <PlayerTransportProvider value={transport}>
    <div className={['lgu-player-container', className].filter(Boolean).join(' ')}>
      <div className="lgu-player" lang={locale} data-session={sessionId}>
        {room.error && <Alert locale={locale} onClose={room.dismiss}>{room.error}</Alert>}
        {room.session
          ? <LivePlayScreen locale={locale} session={room.session} offset={room.offset} connection={room.connection} answer={room.answer} setAnswer={room.setAnswer} busy={room.busy} onSubmit={room.submit} onBack={onLeave} spectator={spectator} />
          : !room.error && <div className="page page--narrow lgu-player-loading" aria-busy="true"><span className="spinner" aria-hidden="true" /><p className="note">{el ? 'Σύνδεση με τη συνεδρία…' : 'Connecting to the session…'}</p></div>}
      </div>
    </div>
  </PlayerTransportProvider>;
}
