'use client';
import { AudioControls } from './audio-controls';
import { MediaImage } from './engine/media';
import { completeAnswer } from './engine/arrangement.ts';
import { MatchInput } from './ui/match-input';
import { OrderInput } from './ui/order-input';
import type { DisplayQuestion, Locale } from './ui-types';

/** A submission is complete when every slot is filled and match answers are distinct. */
export function validAnswer(question: DisplayQuestion, answer: string[]) {
  return completeAnswer(question.kind, answer);
}

/**
 * Renders every question format with Template #1 answer controls. The answer each control writes is
 * unchanged: ordered ids for `order`, one right-hand id per left-hand option for `match`, one id
 * otherwise. The two arranged formats are drag-and-drop controls of their own (app/ui/order-input.tsx,
 * app/ui/match-input.tsx), keyed by the question so a new question — or the same question in a new
 * round or session — starts with nothing picked up or selected.
 */
export function QuestionInput({ question, answer, setAnswer, busy, locale }: {
  question: DisplayQuestion;
  answer: string[];
  setAnswer: (answer: string[]) => void;
  busy: boolean;
  locale: Locale;
}) {
  const el = locale === 'el';
  const instance = `${question.roundId ?? question.sessionId ?? ''}:${question.id}:${question.version}`;
  if (question.kind === 'order') return <>
    <AudioControls items={question.audio} locale={locale} />
    <OrderInput key={instance} question={question} answer={answer} setAnswer={setAnswer} busy={busy} locale={locale} />
  </>;
  if (question.kind === 'match') return <>
    <AudioControls items={question.audio} locale={locale} />
    <MatchInput key={instance} question={question} answer={answer} setAnswer={setAnswer} busy={busy} locale={locale} />
  </>;
  const letters = el ? ['Α', 'Β', 'Γ', 'Δ', 'Ε', 'Ζ'] : ['A', 'B', 'C', 'D', 'E', 'F'];
  return <>
    <AudioControls items={question.audio} locale={locale} />
    <div className={`answers ${question.kind === 'image' ? 'image-answers' : ''}`} role="group" aria-label={el ? 'Απαντήσεις' : 'Answers'}>{question.options.map((option, index) => <button
      type="button"
      key={option.id}
      aria-pressed={answer[0] === option.id}
      className={`answer-option ${answer[0] === option.id ? 'selected' : ''}`}
      disabled={busy}
      onClick={() => setAnswer([option.id])}>
      {question.kind === 'image'
        // Through the media loader, like every other theme picture: a bundled icon resolves against the
        // deployed origin rather than the shell's own bundle, and a private theme's uploaded picture is
        // fetched with the session — the element alone could not carry it.
        ? <MediaImage media={{ url: option.imageUrl ?? '', alt: option.text, kind: 'image' }} alt={option.text} />
        : <><span className="answer-letter" aria-hidden="true">{letters[index]}</span><span>{option.text}</span></>}
    </button>)}</div>
  </>;
}
