import type { Platform } from './types.ts';

// Device Capability Layer — pure types and classification.
//
// Nothing in this file reads `window`, `navigator`, `document` or `process`. Signals come in, a
// DeviceProfile comes out, so the server render, the browser, the tests and a future native adapter
// all go through one function and can be reasoned about deterministically.
//
// THE CAPABILITY-FIRST RULE
// Screens and business logic ask capability and presentation questions:
//   "do I have touch?"  "can I hover?"  "is focus moved with a D-pad?"  "can this device vibrate?"
//   "is this a TV presentation?"  "can this device receive push?"
// They never ask identity questions — "is this iOS?", "is the window wide?", "what does the user
// agent say?". Identity is resolved here, once, and only where it is reliable. Whatever the
// environment cannot know is reported as `unknown` (or as "not detected"), never guessed.
// `tests/device-profile.test.ts` greps `app/` and `src/` for the forbidden patterns.
//
// TWO IDENTITIES, ON PURPOSE
// `PlatformOs` (`types.ts`) is the transport identity: what the backend is told in `x-lgu-client`
// and what it stores in `push_devices.platform`. It stays `web | ios | android` because the API
// validation, the push provider map and a database CHECK constraint depend on it. `DeviceRuntime`
// below describes where the shared core runs, for presentation and capability purposes, and may grow
// without touching the backend: an Android TV shell is still an `android` client to the API.

/** The physical class of device. Only an adapter that knows the hardware may claim one; browser
 * signals always yield `unknown` — a large viewport is not a TV, touch is not a phone. */
export type FormFactor = 'phone' | 'tablet' | 'desktop' | 'tv' | 'kiosk' | 'unknown';
export const FORM_FACTORS: readonly FormFactor[] = ['phone', 'tablet', 'desktop', 'tv', 'kiosk', 'unknown'];

/** Where the shared core is running. `browser` is the web adapter; the others are placeholders a
 * future adapter may declare. None of them is implemented, supported or shipped today. */
export type DeviceRuntime = 'browser' | 'android' | 'ios' | 'tvos' | 'android-tv' | 'tizen' | 'webos' | 'desktop-shell' | 'kiosk-shell' | 'unknown';
export const DEVICE_RUNTIMES: readonly DeviceRuntime[] = ['browser', 'android', 'ios', 'tvos', 'android-tv', 'tizen', 'webos', 'desktop-shell', 'kiosk-shell', 'unknown'];

export type PointerPrecision = 'none' | 'coarse' | 'fine' | 'unknown';

/** What the learner can actually do, independent of the operating system. Several may be true at
 * once (a touch laptop has touch, a fine pointer, hover and a keyboard). `false` means "not detected
 * or not declared", never "proven absent". */
export type InputCapabilities = {
  /** A touch digitiser is present (`navigator.maxTouchPoints > 0`, or `(any-pointer: coarse)` when the count is unavailable). */
  touch: boolean;
  /** A fine pointing device — mouse, trackpad, stylus — is attached (`(any-pointer: fine)`). */
  finePointer: boolean;
  /** Precision of the primary pointing device (`(pointer: …)`). `none` is what a remote-driven browser typically reports; it is still not proof of a TV. */
  primaryPointer: PointerPrecision;
  /** The primary pointer can hover (`(hover: hover)`), so hover-only affordances are usable. */
  hover: boolean;
  /** Keyboard events drive the interface. True on every browser — a hardware or virtual keyboard can be attached to anything — and a native adapter may declare false for a remote-only shell. */
  keyboard: boolean;
  /** Focus moves with directional keys or a D-pad as the primary navigation. Declared by TV/kiosk adapters only; never inferred on the web. */
  directional: boolean;
  /** A remote control is the primary input. Declared by adapters only. */
  remote: boolean;
  /** A gamepad is currently connected (Gamepad API). */
  gamepad: boolean;
};

/** Viewport size class. The thresholds are the ones `app/globals.css` already uses (600 px, 900 px);
 * the tab bar becomes a header at `expanded`. A size class is a layout fact, not a device identity. */
export type ViewportClass = 'compact' | 'medium' | 'expanded' | 'unknown';
export const VIEWPORT_BREAKPOINTS = { medium: 600, expanded: 900 } as const;

/** The presentation the shared UI should adopt. `tv` and `kiosk` can only come from a declared form
 * factor; the web falls back to the responsive default (`mobile` below the 900 px switch, `desktop`
 * from it), which is exactly what the stylesheet does today. Nothing consumes this yet: presentation
 * adaptations (focus states, D-pad navigation, 10-foot typography) are a later phase. */
export type PresentationProfile = 'mobile' | 'tablet' | 'desktop' | 'tv' | 'kiosk';

/** Raw environment signals. `null` means "the environment cannot report this". Everything is
 * standards-based feature detection; there is deliberately no user-agent field. */
export type DeviceSignals = {
  /** A browser document exists (`window` and `document` are defined). False on the server. */
  browser: boolean;
  viewportWidth: number | null;
  viewportHeight: number | null;
  maxTouchPoints: number | null;
  /** `(pointer: coarse)`, `(pointer: fine)`, `(pointer: none)` — the primary pointer. */
  pointerCoarse: boolean | null;
  pointerFine: boolean | null;
  pointerNone: boolean | null;
  /** `(any-pointer: coarse)`, `(any-pointer: fine)` — any attached pointer. */
  anyPointerCoarse: boolean | null;
  anyPointerFine: boolean | null;
  /** `(hover: hover)` — the primary pointer can hover. */
  hover: boolean | null;
  /** Connected gamepads, when the Gamepad API is available. */
  gamepads: number | null;
};

export const NO_BROWSER_SIGNALS: DeviceSignals = Object.freeze({
  browser: false, viewportWidth: null, viewportHeight: null, maxTouchPoints: null,
  pointerCoarse: null, pointerFine: null, pointerNone: null, anyPointerCoarse: null, anyPointerFine: null,
  hover: null, gamepads: null,
});

/** What an adapter that knows the hardware may declare. Declared values win over inferred ones.
 * This is the contract the Capacitor phase (and any later shell) fills in from its own APIs. */
export type DeclaredDevice = {
  runtime?: DeviceRuntime;
  formFactor?: FormFactor;
  input?: Partial<InputCapabilities>;
};

/** Aggregate view of what this device can do, **derived on every read from the Platform capability
 * adapters** (`platform.haptics.supported` and friends). It is a convenience, never a second source
 * of truth: the adapter's `supported` flag stays authoritative. */
export type DeviceFeatures = {
  /** Key-value storage is available (web: localStorage exists). Says nothing about security. */
  storage: boolean;
  /** Storage is encrypted at rest, as **explicitly guaranteed by the adapter** (`storage.secureAtRest`).
   * Always false on the web (localStorage). Never inferred from `isNative`, the OS or the runtime. */
  secureStorage: boolean;
  push: boolean;
  deepLinks: boolean;
  share: boolean;
  networkStatus: boolean;
  lifecycle: boolean;
  haptics: boolean;
  softKeyboardEvents: boolean;
  localNotifications: boolean;
  statusBar: boolean;
  splashScreen: boolean;
  orientationLock: boolean;
  /** The operating system has a Back affordance this application handles (Android only). */
  systemBack: boolean;
  camera: boolean;
  microphone: boolean;
  files: boolean;
};

export type DeviceProfile = {
  runtime: DeviceRuntime;
  formFactor: FormFactor;
  input: InputCapabilities;
  viewport: ViewportClass;
  presentation: PresentationProfile;
  features: DeviceFeatures;
};

/** The `Platform.device` member. Adapters implement it; screens read it (through `useDeviceProfile`
 * in `app/engine/device.ts`, or directly outside React). */
export type DeviceCapabilities = {
  /** The current profile. Cheap, synchronous, safe on the server (returns the no-browser profile) and
   * referentially stable while nothing changed. */
  profile(): DeviceProfile;
  /** Observe changes — viewport class, pointer/hover characteristics, gamepad connection, or an
   * adapter's own events. Returns the unsubscribe function; the last unsubscribe releases listeners. */
  onChange(listener: (profile: DeviceProfile) => void): () => void;
};

const NO_INPUT: InputCapabilities = Object.freeze({ touch: false, finePointer: false, primaryPointer: 'unknown', hover: false, keyboard: false, directional: false, remote: false, gamepad: false });

export const NO_FEATURES: DeviceFeatures = Object.freeze({
  storage: false, secureStorage: false, push: false, deepLinks: false, share: false, networkStatus: false, lifecycle: false, haptics: false,
  softKeyboardEvents: false, localNotifications: false, statusBar: false, splashScreen: false, orientationLock: false, systemBack: false,
  camera: false, microphone: false, files: false,
});

export function viewportClass(width: number | null): ViewportClass {
  if (width === null || !Number.isFinite(width) || width < 0) return 'unknown';
  if (width >= VIEWPORT_BREAKPOINTS.expanded) return 'expanded';
  if (width >= VIEWPORT_BREAKPOINTS.medium) return 'medium';
  return 'compact';
}

/** Presentation from a (possibly declared) form factor, else the responsive web default. */
export function presentationFor(formFactor: FormFactor, viewport: ViewportClass): PresentationProfile {
  switch (formFactor) {
    case 'tv': return 'tv';
    case 'kiosk': return 'kiosk';
    case 'phone': return 'mobile';
    case 'tablet': return 'tablet';
    case 'desktop': return 'desktop';
    default: return viewport === 'expanded' ? 'desktop' : 'mobile';
  }
}

/** Input capabilities from browser signals alone. Detection only — no inference of a device class. */
export function inferInput(signals: DeviceSignals): InputCapabilities {
  if (!signals.browser) return NO_INPUT;
  const touch = signals.maxTouchPoints !== null ? signals.maxTouchPoints > 0 : signals.anyPointerCoarse === true;
  const finePointer = signals.anyPointerFine === true;
  const mediaQueriesUnavailable = signals.pointerFine === null && signals.pointerCoarse === null && signals.pointerNone === null;
  const primaryPointer: PointerPrecision = signals.pointerFine ? 'fine' : signals.pointerCoarse ? 'coarse' : signals.pointerNone ? 'none' : mediaQueriesUnavailable && touch ? 'coarse' : 'unknown';
  return {
    touch, finePointer, primaryPointer,
    hover: signals.hover === true,
    keyboard: true,
    directional: false,
    remote: false,
    gamepad: (signals.gamepads ?? 0) > 0,
  };
}

/** Derives the aggregate feature view from the authoritative capability adapters. The parameter type
 * deliberately excludes `isNative` and `os`: nothing here may be inferred from identity. */
export function deviceFeatures(platform: Pick<Platform, 'storage' | 'notifications' | 'deepLinks' | 'share' | 'network' | 'lifecycle' | 'haptics' | 'keyboard' | 'localNotifications' | 'statusBar' | 'splashScreen' | 'orientation' | 'systemBack' | 'camera' | 'microphone' | 'files'>): DeviceFeatures {
  return {
    storage: platform.storage.supported,
    // Security is the adapter's explicit statement, never a consequence of availability or of where the code runs.
    secureStorage: platform.storage.supported && platform.storage.secureAtRest === true,
    push: platform.notifications.supported,
    deepLinks: platform.deepLinks.supported,
    share: platform.share.supported,
    networkStatus: platform.network.supported,
    lifecycle: platform.lifecycle.supported,
    haptics: platform.haptics.supported,
    softKeyboardEvents: platform.keyboard.supported,
    localNotifications: platform.localNotifications.supported,
    statusBar: platform.statusBar.supported,
    splashScreen: platform.splashScreen.supported,
    orientationLock: platform.orientation.supported,
    systemBack: platform.systemBack.supported,
    camera: platform.camera.supported,
    microphone: platform.microphone.supported,
    files: platform.files.supported,
  };
}

/**
 * The one classification function. Browser signals give input capabilities and a viewport class;
 * an adapter's declared values give runtime, form factor and any input it knows better; the
 * Platform adapters give the feature view. Nothing else is ever inferred.
 */
export function classifyDevice(signals: DeviceSignals, declared: DeclaredDevice = {}, features: DeviceFeatures = NO_FEATURES): DeviceProfile {
  const input: InputCapabilities = { ...inferInput(signals), ...declared.input };
  const formFactor = declared.formFactor ?? 'unknown';
  const runtime = declared.runtime ?? (signals.browser ? 'browser' : 'unknown');
  const viewport = viewportClass(signals.viewportWidth);
  return { runtime, formFactor, input, viewport, presentation: presentationFor(formFactor, viewport), features };
}

/** The profile of an environment with no browser: what the server render uses, and the hydration
 * snapshot on the client, so server and client markup agree. Frozen at every level, so no consumer can
 * corrupt the shared snapshot. */
const noBrowserProfile = classifyDevice(NO_BROWSER_SIGNALS);
export const NO_BROWSER_PROFILE: DeviceProfile = Object.freeze({ ...noBrowserProfile, input: Object.freeze(noBrowserProfile.input), features: NO_FEATURES });

/** Structural equality, so observers can hand out a stable reference while nothing changed. */
export function sameProfile(a: DeviceProfile, b: DeviceProfile): boolean {
  if (a === b) return true;
  if (a.runtime !== b.runtime || a.formFactor !== b.formFactor || a.viewport !== b.viewport || a.presentation !== b.presentation) return false;
  for (const key of Object.keys(a.input) as (keyof InputCapabilities)[]) if (a.input[key] !== b.input[key]) return false;
  for (const key of Object.keys(a.features) as (keyof DeviceFeatures)[]) if (a.features[key] !== b.features[key]) return false;
  return true;
}
