import type { DeviceCapabilities } from './device.ts';

// Platform abstraction. Business components never ask "is this iOS?"; they ask the platform for a
// capability and get either a working adapter or `supported: false`. The web implementation is real
// where the web can do it. The Capacitor phase plugs native adapters into the same contract in one
// place (app/platform/index.ts) without touching screens or engines.
//
// Device identity (form factor, input, presentation, runtime) is a separate, additive concept in
// device.ts. It does not widen PlatformOs, and product code must depend on capabilities, not on either.

/** Transport identity: the value sent in `x-lgu-client` and stored in `push_devices.platform`. The API
 * validation (`PLATFORM_INVALID`), the push provider map and a database CHECK constraint all depend on
 * exactly these three values. A new device class (TV, kiosk, desktop shell) is described by
 * `DeviceRuntime` in device.ts and still identifies itself to the backend as one of these. */
export type PlatformOs = 'web' | 'ios' | 'android';
export type Capability = { supported: boolean };

/** Key-value storage. `supported` says whether storage is available at all; `secureAtRest` is an explicit
 * statement by the adapter that the backing store is encrypted at rest (native Keychain / Keystore). It is
 * never inferred from `isNative`, the OS or the runtime, and availability never implies security.
 * Web: localStorage — available where it exists, **not** secure at rest. */
export type KeyValueStorage = Capability & {
  /** True only when this adapter guarantees encrypted-at-rest storage. localStorage is always false. */
  readonly secureAtRest: boolean;
  get(key: string): Promise<string | null>;
  set(key: string, value: string): Promise<void>;
  remove(key: string): Promise<void>;
};

export type PushPermission = 'granted' | 'denied' | 'prompt' | 'unsupported';
export type PushRegistration = { platform: PlatformOs; provider: 'webpush' | 'fcm' | 'apns'; subscription: unknown; endpointKey: string };
export type Notifications = Capability & {
  permission(): Promise<PushPermission>;
  /** Must be called from a user gesture. Returns the registration to send to the backend. */
  requestPermissionAndSubscribe(applicationServerKey: string): Promise<{ permission: PushPermission; registration: PushRegistration | null }>;
  currentRegistration(applicationServerKey?: string): Promise<PushRegistration | null>;
  unsubscribe(): Promise<boolean>;
  onMessage(listener: (message: { type: string; [key: string]: unknown }) => void): () => void;
};

export type DeepLinks = Capability & {
  /** Fires with an application path when the platform opens the app from a link or a notification. */
  onOpen(listener: (path: string) => void): () => void;
};

export type Share = Capability & { share(data: { title?: string; text?: string; url?: string }): Promise<boolean> };
export type Network = Capability & { online(): boolean; onChange(listener: (online: boolean) => void): () => void };
export type Lifecycle = Capability & { onChange(listener: (state: 'active' | 'background') => void): () => void };
export type Haptics = Capability & { impact(style: 'light' | 'medium' | 'heavy'): Promise<void> };
export type Keyboard = Capability & { onChange(listener: (visible: boolean) => void): () => void };
export type LocalNotifications = Capability & { schedule(input: { id: string; title: string; body: string; at: number; route?: string }): Promise<boolean>; cancel(id: string): Promise<void> };
export type StatusBar = Capability & { setStyle(style: 'light' | 'dark'): Promise<void> };
export type SplashScreen = Capability & { hide(): Promise<void> };
export type Orientation = Capability & { lock(mode: 'portrait' | 'landscape' | 'any'): Promise<void> };

/** The operating system's own Back affordance.
 *
 * Android has one and it is a system button; iOS navigates with in-app gestures and has none; a
 * browser's Back is history, which the application already follows through `deepLinks`. So this is
 * `supported: false` everywhere except an Android shell, and product code asks the capability rather
 * than asking which operating system it is on.
 *
 * `onPress` hands the press to the application **instead of** any default platform navigation: once
 * anything is listening, the listener decides every time, including the press that leaves the app.
 * `canGoBack` is the shell's own statement about its history stack, not a guess by the application.
 *
 * `leaveApp` is the other half of that bargain. Having taken the press, the application must be able
 * to give it back, and this is what does it: the app leaves the foreground the way Android leaves it
 * when Back is pressed at a task's root. */
export type SystemBack = Capability & {
  onPress(listener: (event: { canGoBack: boolean }) => void): () => void;
  leaveApp(): Promise<void>;
};

/** Camera, microphone and file access are declared here only so a future feature has a single place to
 * plug into. No permission exists in any manifest until a product feature needs one. */
export type Camera = Capability;
export type Microphone = Capability;
export type FileAccess = Capability;

/** How the session credential reaches the backend.
 *
 * `cookie` — the browser holds an HttpOnly cookie it cannot read and attaches it to same-origin
 * requests. Nothing in the application ever sees the token. This is the stronger option and it stays
 * the web behaviour.
 *
 * `bearer` — the shell serves its UI from the device, so every API call is cross-site and a
 * SameSite=Lax cookie is correctly not sent. The client asks for the session token and presents it in
 * the Authorization header (`app/engine/session.ts`). It is an explicit credential rather than an
 * ambient one, which is what lets the backend accept it safely without weakening the cookie. */
export type SessionTransport = 'cookie' | 'bearer';

export type Platform = {
  readonly isNative: boolean;
  readonly os: PlatformOs;
  readonly appVersion: string;
  /** How this platform carries the session. Read by the API client, never by a screen. */
  readonly sessionTransport: SessionTransport;
  /** Sent with every API request so the backend can apply the minimum-version policy. */
  clientHeader(): string;
  storage: KeyValueStorage;
  notifications: Notifications;
  deepLinks: DeepLinks;
  share: Share;
  network: Network;
  lifecycle: Lifecycle;
  haptics: Haptics;
  keyboard: Keyboard;
  localNotifications: LocalNotifications;
  statusBar: StatusBar;
  splashScreen: SplashScreen;
  orientation: Orientation;
  systemBack: SystemBack;
  camera: Camera;
  microphone: Microphone;
  files: FileAccess;
  /** Device Profile: form factor, input capabilities, viewport class, presentation and the derived feature view. */
  device: DeviceCapabilities;
};

export const unsupported = <T extends Capability>(extra: Omit<T, 'supported'>): T => ({ supported: false, ...extra }) as T;

export type { DeviceCapabilities, DeviceFeatures, DeviceProfile, DeviceRuntime, DeclaredDevice, DeviceSignals, FormFactor, InputCapabilities, PointerPrecision, PresentationProfile, ViewportClass } from './device.ts';
