import { Capacitor } from '@capacitor/core';
import { App } from '@capacitor/app';
import { Network } from '@capacitor/network';
import { Haptics, ImpactStyle } from '@capacitor/haptics';
import { Keyboard } from '@capacitor/keyboard';
import { StatusBar, Style as StatusBarStyle } from '@capacitor/status-bar';
import { SplashScreen } from '@capacitor/splash-screen';
import { Preferences } from '@capacitor/preferences';
import type { Platform, PlatformOs } from './types.ts';
import { createWebPlatform } from './web.ts';
import { createNativePlatform, type NativePlugins } from './native.ts';

// The single place where the running platform is chosen. Every screen, engine and API call goes
// through `getPlatform()`, so this decision is made once, at the boundary, and nothing downstream
// asks which operating system it is running on.

const APP_VERSION = process.env.NEXT_PUBLIC_LGU_APP_VERSION || '0.0.0';

/**
 * The transport identity of the current runtime, from Capacitor's own detection.
 *
 * `Capacitor.getPlatform()` returns `'web'` whenever the bridge is absent — in a browser, in the
 * Node test runner and during a server render — so this is safe everywhere and needs no guard of its
 * own. Anything that is neither `ios` nor `android` is treated as the web: a runtime this build does
 * not know is not a native shell, and guessing would be worse than falling back.
 */
export function detectPlatformOs(capacitor: Pick<typeof Capacitor, 'isNativePlatform' | 'getPlatform'> = Capacitor): PlatformOs {
  if (!capacitor.isNativePlatform()) return 'web';
  const platform = capacitor.getPlatform();
  return platform === 'ios' || platform === 'android' ? platform : 'web';
}

// Two plugins take a string enum rather than a string. The adapter stays plugin-agnostic — it is
// tested with fakes — so the enum values are mapped here, at the binding, instead of being cast.
const IMPACT_STYLES: Record<string, ImpactStyle> = { HEAVY: ImpactStyle.Heavy, MEDIUM: ImpactStyle.Medium, LIGHT: ImpactStyle.Light };
const STATUS_BAR_STYLES: Record<string, StatusBarStyle> = { DARK: StatusBarStyle.Dark, LIGHT: StatusBarStyle.Light };

/** The official plugins, bound to the narrow shapes `createNativePlatform` declares. */
const plugins: NativePlugins = {
  // `App` carries both the lifecycle/deep-link listeners and the system Back button.
  app: App,
  network: Network,
  haptics: { impact: ({ style }) => Haptics.impact({ style: IMPACT_STYLES[style] ?? ImpactStyle.Light }) },
  keyboard: Keyboard,
  statusBar: { setStyle: ({ style }) => StatusBar.setStyle({ style: STATUS_BAR_STYLES[style] ?? StatusBarStyle.Light }) },
  splashScreen: SplashScreen,
  preferences: Preferences,
};

let instance: Platform | null = null;
export function getPlatform(): Platform {
  if (instance) return instance;
  const os = detectPlatformOs();
  return instance = os === 'web' ? createWebPlatform() : createNativePlatform(os, plugins, APP_VERSION);
}

/** Test seam: forgets the selected platform so the next `getPlatform()` chooses again. */
export function resetPlatformForTests(): void { instance = null; }

export type { Platform, SessionTransport } from './types.ts';
export type { DeviceProfile, DeviceCapabilities, DeviceFeatures, DeviceRuntime, DeclaredDevice, FormFactor, InputCapabilities, PointerPrecision, PresentationProfile, ViewportClass } from './device.ts';
