import type { Kind } from '../../src/domain/rules.ts';

/**
 * The arrangements a learner builds for the two formats that are answered by moving cards: the
 * sequence of an `order` question and the pairing of a `match` question. Pure functions over the
 * answer arrays the API already expects — an `order` answer is the option ids in the learner's
 * sequence, a `match` answer holds, for every left-hand option in the order shown, the id of the
 * right-hand card placed beside it, or '' while that place is empty.
 *
 * Every gesture the screen offers — a drag, a tap on a card and then on a place, an arrow key on a
 * grabbed card — ends in one of these functions, so a later input device (a remote control, a game
 * pad) adds a way to trigger them and nothing else. None of them decides correctness: the server
 * does that once, at submission (`validateSubmission` and `answerIsCorrect` in src/domain/quiz.ts).
 */

/** A submission is complete when every place is filled and, for a pairing, no card is used twice. */
export function completeAnswer(kind: Kind, answer: readonly string[]): boolean {
  if (answer.length === 0 || answer.some(value => !value)) return false;
  return kind !== 'match' || new Set(answer).size === answer.length;
}

/** The sequence with the card at `from` carried to `to`. A position outside the list leaves it as it is. */
export function moveItem(sequence: readonly string[], from: number, to: number): string[] {
  const next = [...sequence];
  if (from === to || from < 0 || to < 0 || from >= sequence.length || to >= sequence.length) return next;
  const [card] = next.splice(from, 1);
  next.splice(to, 0, card);
  return next;
}

/**
 * The pairing with `cardId` placed at `slot`. A card is placed once: it leaves the place it held
 * before, and the card that held `slot` returns to the available answers (its place becomes '').
 */
export function placeCard(pairing: readonly string[], slot: number, cardId: string): string[] {
  if (slot < 0 || slot >= pairing.length || !cardId) return [...pairing];
  return pairing.map((held, index) => index === slot ? cardId : held === cardId ? '' : held);
}

/** The pairing with `slot` emptied; the card it held is available again. */
export function clearSlot(pairing: readonly string[], slot: number): string[] {
  return pairing.map((held, index) => index === slot ? '' : held);
}

/** The place `cardId` holds, or -1 while it is among the available answers. */
export function slotOf(pairing: readonly string[], cardId: string): number {
  return cardId ? pairing.indexOf(cardId) : -1;
}

/** The cards not yet placed, in the order the question offers them. */
export function unplacedCards(pairing: readonly string[], cardIds: readonly string[]): string[] {
  const placed = new Set(pairing.filter(Boolean));
  return cardIds.filter(id => !placed.has(id));
}

/**
 * The pairing a match question should be rendered with: `answer` when it really describes this
 * question — one entry per left-hand option, every placed card one of this question's right-hand
 * cards, no card twice — and an empty pairing otherwise. Same reason as `orderingFor` in
 * app/engine/ordering.ts: for one render after a question arrives, `answer` still belongs to the
 * previous question, and the empty pairing is exactly what the reset installs a frame later.
 */
export function pairingFor(leftCount: number, cardIds: readonly string[], answer: readonly string[]): string[] {
  const empty = () => Array.from({ length: leftCount }, () => '');
  if (answer.length !== leftCount) return empty();
  const wanted = new Set(cardIds);
  const seen = new Set<string>();
  for (const held of answer) {
    if (held === '') continue;
    if (!wanted.has(held) || seen.has(held)) return empty();
    seen.add(held);
  }
  return [...answer];
}
