'use client';
import { useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';

// A card that turns over. The turn is two half rotations with the content swapped while the card is
// edge-on, so only one face is ever in the document: nothing is mirrored, nothing is announced twice,
// and the two sides may have different heights without a visible jump. Mode-neutral on purpose — Learn
// uses it today, Play can reuse it unchanged.

/** Half-turn timings. The component publishes them as custom properties so CSS and JS cannot drift apart. */
export const TURN = { out: 180, in: 240 } as const;
/** Reduced motion keeps the same shape of transition, as a crossfade. */
export const FADE = { out: 120, in: 160 } as const;

export function usePrefersReducedMotion() {
  const [reduced, setReduced] = useState(false);
  useEffect(() => {
    const query = window.matchMedia?.('(prefers-reduced-motion: reduce)');
    if (!query) return;
    const update = () => setReduced(query.matches);
    update();
    query.addEventListener('change', update);
    return () => query.removeEventListener('change', update);
  }, []);
  return reduced;
}

export type TurnState<F extends string> = { face: F; motion: 'idle' | 'out' | 'in' };

/**
 * Follows `target`: turns the current face away, swaps to the target face, turns it back in.
 * Timers are cleared on unmount and whenever the target changes again, so a card that is left
 * mid-turn never resumes and never fires twice.
 */
export function useCardTurn<F extends string>(target: F, reduced: boolean): TurnState<F> {
  const [state, setState] = useState<TurnState<F>>({ face: target, motion: 'idle' });
  const timers = useRef<ReturnType<typeof setTimeout>[]>([]);
  const turningTo = useRef<F>(target);
  useEffect(() => () => { timers.current.forEach(clearTimeout); timers.current = []; }, []);
  useEffect(() => {
    if (turningTo.current === target) return;
    turningTo.current = target;
    timers.current.forEach(clearTimeout);
    timers.current = [];
    const timing = reduced ? FADE : TURN;
    setState(current => ({ face: current.face, motion: 'out' }));
    timers.current.push(setTimeout(() => {
      setState({ face: target, motion: 'in' });
      timers.current.push(setTimeout(() => setState({ face: target, motion: 'idle' }), timing.in));
    }, timing.out));
  }, [target, reduced]);
  return state;
}

export function CardTurn({ motion, reduced, className = '', children }: {
  motion: TurnState<string>['motion']; reduced: boolean; className?: string; children: ReactNode;
}) {
  const timing = reduced ? FADE : TURN;
  const style = { '--turn-out': `${timing.out}ms`, '--turn-in': `${timing.in}ms` } as CSSProperties;
  return <div className={`card-turn ${reduced ? 'card-turn--fade' : ''} ${className}`} style={style}>
    <div className={`card-turn__card ${motion === 'idle' ? '' : `is-${motion}`}`}>{children}</div>
  </div>;
}
