// Service worker registration. The worker (public/sw.js) handles push events and caches theme media
// with stale-while-revalidate. Registration never blocks rendering and is skipped where unsupported.

let registration: Promise<ServiceWorkerRegistration | null> | null = null;

export function serviceWorkerSupported() {
  return typeof navigator !== 'undefined' && 'serviceWorker' in navigator && typeof window !== 'undefined' && (window.isSecureContext ?? false);
}

export function registerServiceWorker(): Promise<ServiceWorkerRegistration | null> {
  if (!serviceWorkerSupported()) return Promise.resolve(null);
  registration ??= navigator.serviceWorker.register('/sw.js', { scope: '/' }).then(async reg => { await navigator.serviceWorker.ready; return reg; }).catch(() => null);
  return registration;
}
