'use client';
import type { CSSProperties, ReactNode } from 'react';
import type { ComponentKey, ComponentMap, ThemeColors, ThemeDetail, ThemeSummary, VariantOf } from '../../src/domain/theme';
import { componentOption, resolveVariant } from '../../src/domain/theme';

// Component registry: the finite set of presentation components a theme document may select, each with
// its bundled variants. A definition chooses a component variant and allowlisted options; it can never
// inject markup or code. Unknown variants degrade to the default so older builds keep rendering.

export type ThemeLike = Pick<ThemeSummary, 'components' | 'colors' | 'typography'> | null | undefined;

export function variantOf<K extends ComponentKey>(theme: ThemeLike, component: K): VariantOf<K> {
  return resolveVariant(component, theme?.components?.[component]?.variant);
}

export function optionOf<T extends boolean | number | string>(theme: ThemeLike, component: ComponentKey, option: string, fallback: T): T {
  return componentOption(theme?.components as ComponentMap | undefined, component, option, fallback);
}

/** Allowlisted colour tokens applied as CSS custom properties on a session container. */
export function themeStyle(theme: ThemeLike): CSSProperties | undefined {
  const colors: ThemeColors = theme?.colors ?? {};
  const style: Record<string, string> = {};
  if (colors.accent) style['--accent'] = colors.accent;
  if (colors.accentTint) style['--accent-tint'] = colors.accentTint;
  if (colors.accentInk) style['--accent-ink'] = colors.accentInk;
  if (theme?.typography?.display === 'sans') style['--font-display'] = 'var(--font-body)';
  return Object.keys(style).length ? style as CSSProperties : undefined;
}

/** Wraps a screen so theme tokens apply to everything inside it. */
export function ThemeScope({ theme, className, children }: { theme: ThemeLike; className?: string; children: ReactNode }) {
  return <div className={className} style={themeStyle(theme)}>{children}</div>;
}

/** The intro presentation a theme resolved for the current language: a video when one exists, otherwise text. */
export function introVariant(theme: ThemeLike, intro: ThemeDetail['intro'] | undefined): 'video' | 'text' {
  const requested = variantOf(theme, 'learn.intro');
  if (requested === 'video') return intro?.video ? 'video' : 'text';
  if (requested === 'text') return 'text';
  return intro?.video ? 'video' : 'text';
}
