'use client';
import { useEffect, useState, type ReactNode } from 'react';
import { BackButton, Button, Card, PageContainer, Pill } from '../ui/primitives';
import { TimerRing } from '../ui/session';
import { AnswerReveal } from '../ui/answer-reveal';
import { QuestionInput, validAnswer } from '../question-input';
import type { LiveSessionView, LiveStandingView, Locale } from '../ui-types';
import { liveViewer, type LiveStreamStatus } from '../engine/live';

/**
 * The live game as a participant lives it: the room, a question the host is about to open, the
 * open question with its countdown, the wait after answering, the reveal with this account's own
 * result, and the session's final ranking. The server decides every step; this screen never moves
 * on by itself, and before the reveal it holds no correct answer to show.
 *
 * As a *spectator* — the audience screen on a projector, opened from the host's controls — it is the
 * same screen in the same phases with nothing personal and nothing to press: the room with the way
 * in (`access`, the code and the QR a class reads off the wall), the question with its countdown and
 * its answer controls shown but disabled, the closed question, the public reveal with the ranking, and
 * the final ranking. What the players see, at the moment they see it.
 *
 * The *host* — the organiser mounted in the room without being a participant of it, as a partner's page
 * mounts the player for its moderator — sees what the audience sees, in the player's own frame: never a
 * personal line («Δεν απάντησες…») about a game they run and do not play. Who is who is `liveViewer`.
 */
export function LivePlayScreen({ locale, session, offset, connection, answer, setAnswer, busy, onSubmit, onBack, spectator = false, access = null }: {
  locale: Locale;
  session: LiveSessionView;
  /** `serverTime - Date.now()` as the stream last measured it; the countdown is shown against the server's clock. */
  offset: number;
  connection: LiveStreamStatus;
  answer: string[];
  setAnswer: (answer: string[]) => void;
  busy: boolean;
  onSubmit: () => void;
  /** Leaving, for a participant; for a spectator, the way back to the host's controls when there is one (a packaged shell). */
  onBack?: () => void;
  spectator?: boolean;
  /** The spectator's lobby shows how to get in: the host's access panel in its display shape. */
  access?: ReactNode;
}) {
  const el = locale === 'el';
  const [now, setNow] = useState(Date.now());
  useEffect(() => {
    if (session.phase !== 'open') return;
    const timer = setInterval(() => setNow(Date.now()), 200);
    return () => clearInterval(timer);
  }, [session.phase, session.phaseVersion]);
  const question = session.question;
  const seconds = question?.deadline ? Math.max(0, Math.ceil((question.deadline - (now + offset)) / 1000)) : 0;
  // The question in the shape the shared answer controls take: what to show, never what is correct.
  const display = question ? { id: question.id, version: 0, kind: question.kind, prompt: question.prompt, options: question.options, rightOptions: question.rightOptions, number: question.index + 1, total: question.total, deadline: question.deadline ?? undefined } : null;
  const viewer = liveViewer(session, spectator);
  const player = viewer === 'player';
  // Someone in the player's frame who does not play: the host, or an account watching without having joined. The
  // audience screen keeps its own wording.
  const watching = !player && !spectator;
  const answered = session.own !== null;
  const eligible = session.me !== null && !session.me.removed && session.question !== null && session.phase === 'open' && session.me.joinedPhaseVersion < session.phaseVersion;
  const number = (value: number) => new Intl.NumberFormat(el ? 'el-GR' : 'en-US').format(value);
  const connectionNote = connection === 'reconnecting' ? (el ? 'Επανασύνδεση…' : 'Reconnecting…') : connection === 'connecting' ? (el ? 'Σύνδεση…' : 'Connecting…') : null;
  // A guest, or an account that entered an open game without a membership, has no event screen to return to.
  const backLabel = session.eventAccess ? (el ? 'Πίσω στη διοργάνωση' : 'Back to the event') : (el ? 'Τέλος' : 'Done');
  const inRoom = session.participants.filter(p => !p.removed).length;
  const questionEyebrow = question ? (el ? `ΕΡΩΤΗΣΗ ${question.index + 1} ΑΠΟ ${question.total}` : `QUESTION ${question.index + 1} OF ${question.total}`) : '';

  return <PageContainer width={spectator ? 'default' : 'narrow'} className={spectator ? 'live-screen live-audience' : 'live-screen'}>
    <div className="session-bar">
      {!spectator && onBack && <BackButton onClick={onBack} label={el ? 'Έξοδος από τη συνεδρία' : 'Leave the session'}>{el ? 'Έξοδος' : 'Leave'}</BackButton>}
      {spectator && onBack && <BackButton onClick={onBack} label={el ? 'Πίσω στον έλεγχο της συνεδρίας' : 'Back to the session controls'}>{el ? 'Έλεγχος' : 'Controls'}</BackButton>}
      <span className="session-title">{session.eventTitle} · {session.themeTitle}</span>
      {spectator && <Pill tone="neutral" icon="eye">{el ? 'Οθόνη κοινού' : 'Audience screen'}</Pill>}
      {viewer === 'host' && <Pill tone="neutral" className="live-host-pill">{el ? 'Διοργανωτής' : 'Organiser'}</Pill>}
      {connectionNote && <span className="live-connection" role="status">{connectionNote}</span>}
    </div>

    {player && session.me?.removed && <Card tint="orange"><p>{el ? 'Ο διοργανωτής σε αφαίρεσε από τη συνεδρία. Το ιστορικό σου διατηρείται.' : 'The organiser removed you from the session. Your history is kept.'}</p></Card>}

    {session.phase === 'lobby' && <Card tint="blue" className="live-lobby">
      <span className="eyebrow">{el ? 'ΖΩΝΤΑΝΟ ΠΑΙΧΝΙΔΙ' : 'LIVE GAME'}</span>
      <h1>{watching
        ? (el ? 'Η αίθουσα είναι ανοιχτή. Περιμένουμε να ξεκινήσει το παιχνίδι.' : 'The room is open. Waiting for the game to start.')
        : (el ? 'Είσαι μέσα! Περιμένουμε να ξεκινήσει το παιχνίδι.' : 'You are in! Waiting for the game to start.')}</h1>
      <p className="lead">{el ? `${session.hostNickname} θα ξεκινήσει το παιχνίδι. ${session.questionCount} ερωτήσεις, όλοι μαζί.` : `${session.hostNickname} will start the game. ${session.questionCount} questions, everyone together.`}</p>
      <p className="note">{el ? `${inRoom} στην αίθουσα` : `${inRoom} in the room`}{player && session.me?.kind === 'guest' ? (el ? ` · παίζεις ως ${session.participants.find(p => p.participantId === session.me?.participantId)?.nickname ?? ''}` : ` · playing as ${session.participants.find(p => p.participantId === session.me?.participantId)?.nickname ?? ''}`) : ''}</p>
    </Card>}
    {session.phase === 'lobby' && spectator && access}

    {session.phase === 'prepare' && question && <Card tint="blue" className="live-prepare">
      <span className="eyebrow">{questionEyebrow}</span>
      <h1>{question.prompt}</h1>
      <p className="lead">{el ? 'Ετοιμάσου — ο διοργανωτής ανοίγει τις απαντήσεις.' : 'Get ready — the organiser is about to open the answers.'}</p>
    </Card>}

    {session.phase === 'open' && question && <div className="live-open">
      <div className="question-head">
        <span className="eyebrow">{questionEyebrow}</span>
        <TimerRing seconds={seconds} limit={question.timeLimitSeconds} locale={locale} />
      </div>
      <h1 className="question-prompt">{question.prompt}</h1>
      {!player
        // The very controls a player holds, shown and disabled (`busy`, the controls' own way of taking no answer): the
        // audience and the host — and a screen reader — read every option, nobody answers from the wall. Not `inert`: that would
        // take the options out of the accessibility tree along with the ability to press them.
        ? <div className="live-spectator-controls"><QuestionInput question={display!} answer={answer} setAnswer={() => {}} busy locale={locale} /></div>
        : answered
          ? <Card tint="green" className="live-answered"><p><strong>{el ? 'Η απάντησή σου καταχωρήθηκε.' : 'Your answer is in.'}</strong> {el ? 'Περίμενε την αποκάλυψη.' : 'Wait for the reveal.'}</p></Card>
          : eligible
            ? <>
                <QuestionInput question={display!} answer={answer} setAnswer={setAnswer} busy={busy} locale={locale} />
                <div className="topic-cta"><Button size="lg" block iconEnd="arrow-right" disabled={busy || seconds === 0 || !display || !validAnswer(display, answer)} onClick={onSubmit}>{el ? 'Υποβολή απάντησης' : 'Submit answer'}</Button></div>
              </>
            : <Card tint="orange"><p>{el ? 'Η ερώτηση άνοιξε πριν μπεις· μετράς από την επόμενη.' : 'The question opened before you came in; you count from the next one.'}</p></Card>}
      <p className="note live-count" role="status">{el ? `${session.answered} από ${session.eligible} απάντησαν` : `${session.answered} of ${session.eligible} answered`}</p>
    </div>}

    {session.phase === 'closed' && question && <Card tint="blue" className="live-closed">
      <span className="eyebrow">{questionEyebrow}</span>
      <h1>{el ? 'Οι απαντήσεις έκλεισαν' : 'Answers are closed'}</h1>
      <p className="lead">{el ? 'Ο διοργανωτής αποκαλύπτει τη σωστή απάντηση σε λίγο.' : 'The organiser reveals the right answer shortly.'}</p>
      <p className="note">{el ? `${session.answered} από ${session.eligible} απάντησαν` : `${session.answered} of ${session.eligible} answered`}</p>
    </Card>}

    {session.phase === 'reveal' && question && session.reveal && <div className="live-reveal">
      <AnswerReveal locale={locale} eyebrow={questionEyebrow}
        question={display!}
        // The audience and the host see the public reveal: the right answer marked, nobody's own. A player sees their own answer against it.
        correct={player ? session.own?.correct ?? false : true} submitted={player ? session.own?.submitted ?? [] : session.reveal.correct} correctIds={session.reveal.correct} solution={session.reveal.explanation} publicVerdict={watching} />
      {!player
        ? <p className="live-count">{el ? `${session.reveal.answered} από ${session.reveal.eligible} απάντησαν` : `${session.reveal.answered} of ${session.reveal.eligible} answered`}</p>
        : <Card tint={session.own?.correct ? 'green' : 'orange'} className="live-own">
          {session.own
            ? <p><strong>{session.own.correct ? (el ? `+${number(session.own.points)} πόντοι` : `+${number(session.own.points)} points`) : (el ? 'Λάθος αυτή τη φορά.' : 'Not this time.')}</strong> {el ? `Απάντησες σε ${(session.own.elapsedMs / 1000).toFixed(1)} δευτ.` : `You answered in ${(session.own.elapsedMs / 1000).toFixed(1)} s.`}</p>
            : <p>{el ? 'Δεν απάντησες σε αυτή την ερώτηση.' : 'You did not answer this question.'}</p>}
        </Card>}
      <Standings locale={locale} rows={session.standings} me={spectator ? null : session.me?.participantId ?? null} />
    </div>}

    {session.phase === 'finished' && <div className="live-finished">
      <Card tint="green">
        <span className="eyebrow">{el ? 'ΤΟ ΠΑΙΧΝΙΔΙ ΟΛΟΚΛΗΡΩΘΗΚΕ' : 'THE GAME IS OVER'}</span>
        <h1>{el ? 'Κατάταξη της συνεδρίας' : 'Session ranking'}</h1>
        <p className="note">{el ? 'Τα αποτελέσματα μένουν στη διοργάνωση και δεν μετρούν στη γενική βαθμολογία.' : 'Results stay with the event and never count towards the general score.'}</p>
      </Card>
      <Standings locale={locale} rows={session.standings} me={spectator ? null : session.me?.participantId ?? null} limit={spectator ? 20 : 50} />
      {!spectator && onBack && <div className="topic-cta"><Button size="lg" block iconEnd="arrow-right" onClick={onBack}>{backLabel}</Button></div>}
    </div>}

    {session.phase === 'cancelled' && <Card tint="orange">
      <h1>{el ? 'Η συνεδρία ακυρώθηκε' : 'The session was cancelled'}</h1>
      {!spectator && onBack && <div className="topic-cta"><Button size="lg" block onClick={onBack}>{backLabel}</Button></div>}
    </Card>}
  </PageContainer>;
}

export function Standings({ locale, rows, me, limit = 10 }: { locale: Locale; rows: LiveStandingView[]; me: string | null; limit?: number }) {
  const el = locale === 'el';
  if (rows.length === 0) return null;
  const number = (value: number) => new Intl.NumberFormat(el ? 'el-GR' : 'en-US').format(value);
  return <div className="section live-standings">
    <div className="section-title"><h2>{el ? 'Κατάταξη' : 'Ranking'}</h2></div>
    <ol className="ranking">
      {rows.slice(0, limit).map(row => <li key={row.participantId} className={row.participantId === me ? 'me' : ''}>
        <span className="rank">{row.rank}</span>
        <span className="name">{row.nickname}</span>
        <Pill tone={row.rank === 1 ? 'orange' : 'neutral'}>{number(row.total)} {el ? 'π.' : 'pts'}</Pill>
        <span className="detail">{row.correct} {el ? 'σωστές' : 'correct'}</span>
      </li>)}
    </ol>
  </div>;
}
